const rtdal007710Source0001 = `diagnose.lppm <- function(object, ..., type="raw", which="all", 
                         sigma=NULL, 
                         cumulative=TRUE,
                         plot.it = TRUE, rv = NULL, 
                         compute.sd=is.poisson(object), compute.cts=TRUE,
                         envelope=FALSE, nsim=39, nrank=1,
                         typename, oldstyle=FALSE, 
                         splineargs=list(spar=0.5))
{
  asked.newstyle <- !missing(oldstyle) && !oldstyle

  stopifnot(is.lppm(object))
  if(is.marked(object))
    stop("Sorry, this is not yet implemented for marked models")
  
  ## check whether model originally came from replicated data
  is.subfit <- (object$fit$method == "mppm")

  ## -------------  Interpret arguments --------------------------

  ## match type argument
  type <- pickoption("type", type,
                     c(eem="eem",
                       raw="raw",
                       inverse="inverse",
                       pearson="pearson",
                       Pearson="pearson"))
  if(missing(typename))
    typename <- switch(type,
                       eem="exponential energy weights",
                       raw="raw residuals",
                       inverse="inverse-lambda residuals",
                       pearson="Pearson residuals")

  ## 'which' is multiple choice with exact matching 
  optionlist <- c("all", "marks", "smooth", "x", "y", "sum")

  if(!all(m <- which %in% optionlist))
    stop(paste("Unrecognised choice(s) of",
               paste(sQuote("which"), ":", sep=""),
               paste(which[!m], collapse=", ")))

  opt <- list()
  opt$all <- "all" %in% which
  opt$marks <-  ("marks" %in% which)   | opt$all
  opt$smooth <- ("smooth" %in% which)  | opt$all
  opt$xmargin <- (("x" %in% which)       | opt$all) && !cumulative
  opt$ymargin <- (("y" %in% which)       | opt$all) && !cumulative
  opt$xcumul <-  (("x" %in% which)       | opt$all) && cumulative
  opt$ycumul <-  (("y" %in% which)       | opt$all) && cumulative
  opt$sum <-     ("sum" %in% which)      | opt$all

  ## compute and plot estimated standard deviations?
  ## yes for Poisson, no for other models, unless overridden
  if(!missing(compute.sd))
    plot.sd <- compute.sd
  else
    plot.sd <- list(...)$plot.sd
  if(is.null(plot.sd))
    plot.sd <- is.poisson(object)
  if(missing(compute.sd))
    compute.sd <- plot.sd

  ## default for mppm objects is oldstyle=TRUE
  if(compute.sd && is.subfit) {
    if(!asked.newstyle) {
      ## silently change default
      oldstyle <- TRUE
    } else {
      stop(paste("Variance calculation for a subfit of an mppm object",
                 "is only implemented for oldstyle=TRUE"),
           call.=FALSE)
    }
  }
    
  ## interpolate the density of the residual measure?
  if(missing(compute.cts)) {
    plot.neg <- resolve.defaults(list(...),
                                 formals(plot.diagppm)["plot.neg"])$plot.neg
    ## only if it is needed for the mark plot
    compute.cts <- opt$marks && (plot.neg != "discrete")
  }

  ## -------  DO THE CALCULATIONS -----------------------------------
  RES <-  diagLppmEngine(object, type=type, typename=typename,
                         opt=opt, sigma=sigma, 
                         compute.sd=compute.sd,
                         compute.cts=compute.cts,
                         envelope=envelope, nsim=nsim, nrank=nrank,
                         rv=rv, oldstyle=oldstyle,
                         splineargs=splineargs,
                         ...)

  RES$typename <- typename
  RES$opt <- opt
  RES$compute.sd <- compute.sd
  RES$compute.cts <- compute.cts
  
  class(RES) <- "diaglppm"

  ## -------  PLOT --------------------------------------------------
  if(plot.it) 
    plot(RES, ...)

  return(RES)
}`

const rtdal007710Source0002 = "diagLppmEngine <- function(object, ..., type=\"eem\", typename, opt,\n                           sigma=NULL,\n                           compute.sd=is.poisson(object),\n                           compute.cts=TRUE,\n                           envelope=FALSE, nsim=39, nrank=1,\n                           rv=NULL, oldstyle=FALSE,\n                           splineargs = list(spar=0.5),\n                           verbose=TRUE)\n{\n  if(is.marked(object))\n    stop(\"Sorry, this is not yet implemented for marked models\")\n\n  ## original point pattern data on network\n  X <- data.lppm(object)\n  L <- as.linnet(X)\n\n  ## quadrature points (2D) and weights\n  Q <- quad.ppm(object)\n  U2D <- union.quad(Q)\n  Qweights <- w.quad(Q)\n  W <- Window(Q)\n\n  ## quadrature points on the network\n  U <- attr(Q, \"situ\") %orifnull% lpp(U2D, L)\n\n  ## \n  ppmfit <- as.ppm(object)\n\n  ## -------------- Calculate residuals/weights -------------------\n\n  ## Discretised residuals\n\n  if(type == \"eem\") {\n    residval <- if(!is.null(rv)) rv else eem(object, check=FALSE)\n    residval <- as.numeric(residval)\n    Y <- X %mark% residval\n  } else {\n    if(!is.null(rv) && !inherits(rv, \"msr\"))\n      stop(\"rv should be a measure (object of class msr)\")\n    residobj <-\n      if(!is.null(rv)) rv else residuals(object, type=type, check=FALSE)\n    residval <- with(residobj, \"increment\")\n    if(ncol(as.matrix(residval)) > 1L)\n      stop(\"Not implemented for vector-valued residuals; use [.msr to split into separate components\")\n    Y <- U %mark% residval\n  }\n\n  ## Atoms and density of measure\n\n  Ymass <- NULL\n  Ycts  <- NULL\n  Ydens <- NULL\n\n  if(compute.cts) {\n    if(type == \"eem\") {\n      Ymass <- Y\n      Ycts  <- U %mark% (-1)\n      Ydens <- as.linim(-1, L)\n    } else {\n      atoms <- with(residobj, \"is.atom\")\n      masses <- with(residobj, \"discrete\")\n      cts    <- with(residobj, \"density\")\n      if(!is.null(atoms) && !is.null(masses) && !is.null(cts)) {\n        Ymass <- (U %mark% masses)[atoms]\n        Ycts    <- U %mark% cts\n        ## remove NAs (as opposed to zero cif points)\n        if(!all(ok <- is.finite(cts))) {\n          U <- U[ok]\n          Ycts <- Ycts[ok]\n          cts  <- cts[ok]\n          Qweights <- Qweights[ok]\n        }\n        ## interpolate continuous part to yield an image for plotting\n        if(type == \"inverse\" && all(cts != 0)) {\n          Ydens <- as.linim(-1, L)\n        } else if(is.stationary(object) && is.poisson(object)) {\n          ## all values of `cts' will be equal\n          Ydens <- as.linim(cts[1L], L)\n        } else {\n          smallsigma <- max(nndist(Ycts))\n          Ujitter <- rjitter(U, smallsigma)\n          Ydens <- Smooth(Ujitter %mark% marks(Ycts),\n                          sigma=smallsigma,\n                          weights=Qweights,\n                          edge=TRUE, ...)\n        }\n      }\n    }\n  }\n    \n  ## ------------ start collecting results -------------------------\n  \n  result <- list(type=type,\n                 Y=Y,\n                 W=W,\n                 Ymass=Ymass,\n                 Ycts=Ycts,\n                 Ydens=Ydens)\n\n  ## ------------- smoothed field ------------------------------\n\n  Z <- NULL\n  if(opt$smooth || opt$xcumul || opt$ycumul || opt$xmargin || opt$ymargin) {\n    if(is.null(sigma))\n      sigma <- 0.07 * diameter(W)\n    Ycm <- marks(Y)\n    ok <- is.finite(Ycm)\n    if(all(ok)) {\n      Z <- density(Y, sigma, weights=Ycm, edge=TRUE, ...)\n    } else {\n      Z <- density(Y[ok], sigma, weights=Ycm[ok], edge=TRUE, ...)\n    }\n  }\n  if(opt$smooth) {\n    result$smooth <- list(Z = Z, sigma=sigma)\n    if(type == \"pearson\")\n      result$smooth$sdp <- 1/(2 * sigma * sqrt(pi))\n  }\n\n  ## -------------- marginals of smoothed field ------------------------\n\n  if(opt$xmargin) {\n    M <- marginalIntegralOfLinim(Z, \"x\")\n    xx <- M$x\n    fx <- M$marginal\n    if(type == \"eem\") {\n      One <- eval.linim(1 + 0 * Z)\n      EM <- marginalIntegralOfLinim(One, \"x\")\n      Efx <- EM$marginal\n    } else {\n      ## zero\n      Efx <- numeric(length(xx))\n    }\n    result$xmargin <- list(x=xx, xZ=fx, ExZ=Efx)\n  }\n  \n  if(opt$ymargin) {\n    M <- marginalIntegralOfLinim(Z, \"y\")\n    yy <- M$y\n    fy <- M$marginal\n    if(type == \"eem\") {\n      One <- eval.linim(1 + 0 * Z)\n      EM <- marginalIntegralOfLinim(One, \"y\")\n      Efy <- EM$marginal\n    } else {\n      ## zero\n      Efy <- numeric(length(yy))\n    }\n    result$ymargin <- list(y=yy, yZ=fy, EyZ=Efy)\n  }\n  \n\n  \n  ## -------------- cumulative (lurking variable) plots --------------\n\n  ## precompute simulated patterns for envelopes\n  if(identical(envelope, TRUE))\n    envelope <- simulate(object, nsim=nsim, progress=verbose)\n\n  if(opt$xcumul)\n    result$xcumul <- \n    lurking(object, covariate=expression(x),\n            type=type,\n            rv=residval,\n            plot.sd=compute.sd,\n            envelope=envelope, nsim=nsim, nrank=nrank,\n            plot.it=FALSE,\n            typename=typename,\n            covname=\"x coordinate\",\n            oldstyle=oldstyle,\n            check=FALSE,\n            splineargs=splineargs,\n            ...)\n\n  if(opt$ycumul)\n    result$ycumul <- \n    lurking(object, covariate=expression(y),\n            type=type,\n            rv=residval,\n            plot.sd=compute.sd,\n            envelope=envelope, nsim=nsim, nrank=nrank,\n            plot.it=FALSE,\n            typename=typename,\n            covname=\"y coordinate\",\n            oldstyle=oldstyle,\n            check=FALSE,\n            splineargs=splineargs,\n            ...)\n\n  ## -------------- summary numbers --------------\n  \n  if(opt$sum) \n    result$sum <- list(marksum=sum(marks(Y), na.rm=TRUE),\n                       lengthL=volume(L),\n                       sumquad=sum(Qweights),\n                       range=if(!is.null(Z)) range(Z) else NULL)\n\n  return(invisible(result))\n}"

const rtdal007710Source0003 = `plot.diaglppm <-
  function(x, ..., which,
           plot.neg=c("image", "discrete"),
           plot.smooth=c("image", "persp"),
           plot.sd, spacing=0.1, outer=3, 
           srange=NULL, monochrome=FALSE, main=NULL)
{
  opt <- x$opt
  
  plot.neg <- match.arg(plot.neg)
  plot.smooth <- match.arg(plot.smooth)
  
  if(!missing(which)) {
    witches <- c("all", "marks", "smooth", "x", "y", "sum")
    unknown <- is.na(match(which, witches))
    if(any(unknown))
      warning(paste("Unrecognised",
                    ngettext(sum(unknown), "option", "options"),
                    "which =",
                    commasep(sQuote(which[unknown])),
                    ": valid options are",
                    commasep(sQuote(witches))), call.=FALSE)
    oldopt <- opt
    newopt <- list()
    newopt$all <- "all" %in% which
    newopt$marks <-  ("marks" %in% which)   | newopt$all
    newopt$smooth <- ("smooth" %in% which)  | newopt$all
    newopt$xmargin <- (("x" %in% which)       | newopt$all) && oldopt$xmargin
    newopt$ymargin <- (("y" %in% which)       | newopt$all) && oldopt$ymargin
    newopt$xcumul <-  (("x" %in% which)       | newopt$all) && oldopt$xcumul
    newopt$ycumul <-  (("y" %in% which)       | newopt$all)  && oldopt$ycumul
    newopt$sum <-     ("sum" %in% which)      | newopt$all

    illegal <- (unlist(newopt) > unlist(oldopt))
    if(any(illegal)) {
      offending <- paste(names(newopt)[illegal], collapse=", ")
      whinge <- paste("cannot display the following components;\n",
                      "they were not computed: - \n", offending, "\n")
      stop(whinge)
    }

    opt <- newopt
  }

  if(missing(plot.sd)) {
    plot.sd <- x$compute.sd
  } else if(plot.sd && !(x$compute.sd)) {
    warning("can't plot standard deviations; they were not computed")
    plot.sd <- FALSE
  }

  if(!(x$compute.cts) && (plot.neg != "discrete") && (opt$marks || opt$all)) {
    if(!missing(plot.neg))
      warning("can't plot continuous component of residuals; it was not computed")
    plot.neg <- "discrete"
  }
  
  if(opt$all) 
    resid4plot(RES=x,
               plot.neg=plot.neg, plot.smooth=plot.smooth,
               spacing=spacing, outer=outer,
               srange=srange, monochrome=monochrome, main=main, ...)
  else
    resid1plot(RES=x, opt=opt,
               plot.neg=plot.neg, plot.smooth=plot.smooth,
               srange=srange, monochrome=monochrome, main=main, ...)
}`

const rtdal007710Source0004 = `print.diaglppm <- function(x, ...) {
  
  opt <- x$opt
  typename <- x$typename
  
  splat("Model diagnostics", paren(typename))
  splat("Diagnostics available:")
  optkey <- list(all="four-panel plot",
                 marks=paste("mark plot", if(!x$compute.cts)
                   "(discrete representation only)" else NULL),
                 smooth="smoothed residual field",
                 xmargin="x marginal density",
                 ymargin="y marginal density",
                 xcumul="x cumulative residuals",
                 ycumul="y cumulative residuals",
                 sum="sum of all residuals")
  avail <- unlist(optkey[names(opt)[unlist(opt)]])
  names(avail) <- NULL
  cat(paste("\t", paste(avail, collapse="\n\t"), "\n", sep=""))
  
  if(opt$sum) {
    xs <- x$sum
    netname <- "entire network"
    splat("sum of", typename, "in", netname, "=", signif(sum(xs$marksum),4))
    splat("length of", netname, "=", signif(xs$lengthL, 4))
    splat("quadrature total mass =", signif(xs$sumquad, 4))
  }
  if(opt$smooth) {
    splat("range of smoothed field = ", prange(signif(range(x$smooth$Z),4)))
    if(!is.null(sdp <- x$smooth$sdp))
      splat("Null standard deviation of smoothed Pearson residual field:",
            signif(sdp, 4))
  }
  return(invisible(NULL))
}`

