const rtdal007734Source0020 = `as.data.frame.lintess <- function(x, ...) {
  df <- x$df
  if(!is.null(marx <- marks(x))) {
    marx <- as.data.frame(marx)
    if(ncol(marx) == 1L) colnames(marx) <- "marks"
    marx <- marx[as.integer(df$tile), , drop=FALSE]
    df <- cbind(df, marx)
  }
  df <- as.data.frame(df, ...)
  return(df)
}`

const rtdal007734Source0021 = `lineartileindex <- function(seg, tp, Z,
                            method=c("encode", "C", "interpreted")) {
  method <- match.arg(method)
  df <- if(inherits(Z, "lintess")) Z$df else
        if(is.data.frame(Z)) Z else stop("Format of Z is unrecognised")
  switch(method,
         interpreted = {
           n <- length(seg)
           #' extract tessellation data
           tilenames <- levels(df$tile)
           answer <- factor(rep(NA_integer_, n),
                            levels=seq_along(tilenames),
                            labels=tilenames)
           for(i in seq_along(seg)) {
             tpi <- tp[i]
             segi <- seg[i]
             j <- which(df$seg == segi)
             kk <- which(df[j, "t0"] <= tpi & df[j, "t1"] >= tpi)
             answer[i] <- if(length(kk) == 0) NA else df[j[min(kk)], "tile"]
           }
         },
         encode = {
           #' encode locations as numeric
           loc <- seg - 1 + tp
           #' extract tessellation data and sort them
           df <- df[order(df$seg, df$t0), , drop=FALSE]
           m <- nrow(df)
           #' encode breakpoints as numeric
           bks <- with(df, c(seg - 1 + t0, seg[m]))
           #' which piece contains each query point
           jj <- findInterval(loc, bks,
                              left.open=TRUE, all.inside=TRUE,
                              rightmost.closed=TRUE)
           answer <- df$tile[jj]
         },
         C = {
           #' sort query data
           oo <- order(seg, tp)
           seg <- seg[oo]
           tp  <- tp[oo]
           n <- length(seg)
           #' extract tessellation data and sort them
           df <- df[order(df$seg, df$t0), , drop=FALSE]
           m <- nrow(df)
           #' handle factor 
           dftile <- df$tile
           tilecode <- as.integer(dftile)
           tilenames <- levels(dftile)
           #' launch
           z <- .C(SL_lintileindex,
                   n      = as.integer(n),
                   seg    = as.integer(seg),
                   tp     = as.double(tp),
                   dfn    = as.integer(m),
                   dfseg  = as.integer(df$seg),
                   dft0   = as.double(df$t0),
                   dft1   = as.double(df$t1),
                   dftile = as.integer(tilecode),
                   answer = as.integer(integer(n)),
                   PACKAGE="spatstat.linnet")
           z <- z$answer
           z[z == 0] <- NA
           answer <- integer(n)
           answer[oo] <- z
           answer <- factor(answer,
                            levels=seq_along(tilenames),
                            labels=tilenames)
           })
  return(answer)
}`

const rtdal007734Source0022 = `as.function.lintess <- function(x, ...) { as.linfun.lintess(x, ...) }`

const rtdal007734Source0023 = `as.linfun.lintess <- local({

  as.linfun.lintess <- function(X, ..., values=marks(X), navalue=NA) {
    Xdf <- X$df
    tilenames <- levels(Xdf$tile)
    value.is.tile <- is.null(values)
    if(value.is.tile) {
      tilevalues <- factor(tilenames, levels=tilenames)
    } else {
      if(!is.null(dim(values))) values <- values[,1]
      if(length(values) != length(tilenames))
        stop("Length of 'values' should equal the number of tiles", call.=FALSE)
      tilevalues <- values
    }
    f <- function(x, y, seg, tp) {
      k <- as.integer(lineartileindex(seg, tp, Xdf))
      if(!anyNA(k)) {
        result <- tilevalues[k]
      } else {
        ok <- !is.na(k)
        result <- rep(navalue, length(seg))
        result[ok] <- tilevalues[k[ok]]
      }
      return(result)
    }
    g <- linfun(f, X$L)
    attr(g, "explain") <- uitleggen
    return(g)
  }

  uitleggen <- function(x, ...) {
    envf <- environment(attr(x, "f"))
    Xdf <- get("Xdf", envir=envf)
    value.is.tile <- get("value.is.tile", envir=envf) %orifnull% FALSE
    if(value.is.tile) {
      valuename <- "the tile index"
    } else {
      tilevalues <- get("tilevalues", envir=envf)
      valuetype <- typeof(tilevalues)
      valuename <- paste("a value", paren(sQuote(valuetype)),
                         "associated with each tile")
    }
    splat("Function on a network, associated with a tessellation,")
    splat("\treturns", valuename)
    nt <- length(levels(Xdf$tile))
    splat("Tessellation has", nt, ngettext(nt, "tile", "tiles"))
    splat("Function domain:")
    print(as.linnet(x))
    return(invisible(NULL))
  }

  as.linfun.lintess
})`

const rtdal007734Source0024 = `identify.lintess <- function(x, ..., labels=tilenames(x),
                             n=nobjects(x), plot=TRUE,
                             paint=plot, paint.args=list()) {
  verifyclass(x, "lintess")
  check.1.integer(n)
  if (dev.cur() == 1 && interactive()) {
    eval(substitute(plot(X), list(X = substitute(x))))
  }
  if(!missing(labels)) {
    if(!is.null(dim(labels))) labels <- labels[,1]
    labels <- unname(unlist(labels))
    if(length(labels) != nobjects(x))
      stop(paste("The number of", sQuote("labels"),
                 "should equal the number of tiles"),
           call.=FALSE)
  }
  ## extract information
  L <- x$L
  df <- x$df
  B <- Frame(L)
  Bplus <- grow.rectangle(B, max(sidelengths(B))/4)
  V <- vertices(L)
  Vx <- V$x
  Vy <- V$y
  ## extract all pieces of all tiles
  from <- L$from[df$seg]  # index of vertex at left end of network segment
  to <- L$to[df$seg]
  xfrom <- Vx[from]       # x coordinate of vertex at left end of network seg
  yfrom <- Vy[from]
  xto <- Vx[to]
  yto <- Vy[to]
  x0 <- xfrom + (xto - xfrom) * df$t0  # x coord of left end of tile fragment 
  y0 <- yfrom + (yto - yfrom) * df$t0
  x1 <- xfrom + (xto - xfrom) * df$t1
  y1 <- yfrom + (yto - yfrom) * df$t1
  S <- psp(x0, y0, x1, y1, Bplus) # one segment for each row of 'df'
  ## Associate each segment of S with its containing tile
  idmap <- as.integer(df$tile)
  ## 
  if(plot) {
    ## information for annotating
    mids <- midpoints.psp(S)
    poz <- c(1, 2, 4, 3)[(floor(angles.psp(S)/(pi/4)) %% 4) + 1L]
    gp <- graphicsPars("lines")
  }
  ## start identifying
  id <- integer(0)
  while(length(id) < n) {
    xy <- spatstatLocator(1, type="n")
    ## check for interrupt exit
    if(length(xy$x) == 0)
      break
    ## find nearest tile fragment
    X <- ppp(xy$x, xy$y, window=Bplus)
    fragid <- project2segment(X, S)$mapXY
    if(length(fragid) == 0) {
      cat("Query location is too far away\n")
    } else {
      tileid <- idmap[fragid]
      if(tileid %in% id) {
        cat(paste("Tile", tileid, "already selected\n"))
      } else {
        ## add to list
        if(plot || paint) {
          ## Display
          mi <- mids[fragid]
          li <- labels[tileid]
          po <- poz[fragid]
          mix <- mi$x
          miy <- mi$y
          dont.complain.about(li, mix, miy)
          if(plot) 
            do.call.matched(graphics::text.default,
                            resolve.defaults(list(x=quote(mix), 
                                                  y=quote(miy), 
                                                  labels=quote(li)),
                                             list(...),
                                             list(pos=po)))
          if(paint)
            do.call.matched(plot.psp,
                            resolve.defaults(list(x=S[idmap == tileid],
                                                  add=TRUE),
                                             paint.args,
                                             list(...),
                                             list(col="blue", lwd=2)),
                            extrargs=gp)
        }
        id <- c(id, tileid)
      }
    }
  }
  out <- data.frame(id=id, name=tilenames(x)[id])
  marx <- marks(x)
  switch(markformat(marx),
         vector = {
           out <- cbind(out, data.frame(marks=marx[id]))
         },
         dataframe = {
           out <- cbind(out, marx[id, , drop=FALSE])
         },
         {})
  return(out)
}`

