const rtdal007772Source0001 = "AreaInter <- local({\n\n  #' area-interaction conditional intensity potential\n  #'     corresponds to potential -C(x) = n(x) - A(x)/\\pi r^2\n\n  areapot <- \n    function(X,U,EqualPairs,pars,correction, ..., W=as.owin(X)) {\n      #' W is the window to which computations of area will be clipped.\n      #' W=NULL is permissible, meaning no clipping.\n      uhoh <- !(correction %in% c(\"border\", \"none\"))\n      if(any(uhoh)) {\n        nuh <- sum(uhoh)\n        warning(paste(ngettext(nuh, \"Correction\", \"Corrections\"),\n                      commasep(sQuote(correction[uhoh])),\n                      ngettext(nuh,\n                               \"is not supported and was ignored\",\n                               \"are not supported and were ignored\")))\n      }\n      r <- pars$r\n      if(is.null(r)) stop(\"internal error: r parameter not found\")\n      #'\n      if(Poly <- spatstat.options('areainter.polygonal')) {\n        if(is.mask(W)) W <- as.polygonal(W)\n        if(is.mask(Window(X))) Window(X) <- as.polygonal(Window(X))\n        if(is.mask(Window(U))) Window(U) <- as.polygonal(Window(U))\n      }\n      n <- U$n\n      areas <- numeric(n)\n      #' dummy points\n      dummies <- setdiff(seq_len(n), EqualPairs[,2L])\n      if(length(dummies)) \n        areas[dummies] <- areaGain(U[dummies], X, r, W=W, exact=Poly)\n      #' data points represented in U\n      ii <- EqualPairs[,1L]\n      jj <- EqualPairs[,2L]\n      inborder <- (bdist.points(X[ii]) <= r) # sic\n      #' points in border region need clipping\n      if(any(inborder))\n        areas[jj[inborder]] <- areaLoss(X, r, subset=ii[inborder], exact=Poly)\n      #' points in eroded region do not necessarily\n      if(any(ineroded <- !inborder)) {\n        areas[jj[ineroded]] <-\n          areaLoss(X, r, subset=ii[ineroded], W=W, exact=Poly)\n      }\n      return(1 - areas/(pi * r^2))\n    }\n\n  #' fractional area of overlap of two unit discs at distance 2 * z\n  discOverlap <- function(z) {\n    z <- pmax(pmin(z, 1), -1)\n    (2/pi) * (acos(z) - z * sqrt(1 - z^2))\n  }\n  \n  # template object without family, par, version\n  BlankAI <- \n  list(\n         name     = \"Area-interaction process\",\n         creator  = \"AreaInter\",\n         family   = \"inforder.family\", # evaluated later\n         pot      = areapot,\n         par      = list(r = NULL), # to be filled in\n         parnames = \"disc radius\",\n         hasInf   = FALSE,\n         init     = function(self) {\n                      r <- self$par$r\n                      if(!is.numeric(r) || length(r) != 1 || r <= 0)\n                       stop(\"disc radius r must be a positive number\")\n                    },\n         update = NULL,  # default OK\n         print = NULL,    # default OK\n         plot = function(fint, ..., d=NULL, plotit=TRUE) {\n           verifyclass(fint, \"fii\")\n           inter <- fint$interaction\n           unitz <- unitname(fint)\n           if(!identical(inter$name, \"Area-interaction process\"))\n             stop(\"Tried to plot the wrong kind of interaction\")\n           #' fitted interaction coefficient\n           theta <- fint$coefs[fint$Vnames]\n           #' interaction radius\n           r <- inter$par$r\n           xlim <- resolve.1.default(list(xlim=c(0, 1.25 * 2*r)), list(...)) \n           rmax <- max(xlim, d)\n           if(is.null(d)) {\n             d <- seq(from=0, to=rmax, length.out=1024)\n           } else {\n             stopifnot(is.numeric(d) &&\n                       all(is.finite(d)) &&\n                       all(diff(d) > 0))\n           }\n           #' compute interaction between two points at distance d\n           y <- exp(theta * discOverlap(d/(2 * r)))\n           #' compute `fv' object\n           fun <- fv(data.frame(r=d, h=y, one=1),\n                     \"r\", substitute(h(r), NULL), \"h\", cbind(h,one) ~ r,\n                     xlim, c(\"r\", \"h(r)\", \"1\"),\n                     c(\"distance argument r\",\n                       \"maximal interaction h(r)\",\n                       \"reference value 1\"),\n                     unitname=unitz)\n           if(plotit)\n             do.call(plot.fv,\n                     resolve.defaults(list(quote(fun)),\n                                      list(...),\n                                      list(ylim=range(0,1,y))))\n           return(invisible(fun))\n         },\n         #' end of function 'plot'\n         interpret =  function(coeffs, self) {\n           logeta <- as.numeric(coeffs[1L])\n           eta <- exp(logeta)\n           return(list(param=list(eta=eta),\n                       inames=\"interaction parameter eta\",\n                       printable=signif(eta)))\n         },\n         valid = function(coeffs, self) {\n           eta <- ((self$interpret)(coeffs, self))$param$eta\n           return(is.finite(eta))\n         },\n         project = function(coeffs, self) {\n           if((self$valid)(coeffs, self))\n             return(NULL)\n           return(Poisson())\n         },\n         irange = function(self, coeffs=NA, epsilon=0, ...) {\n           r <- self$par$r\n           if(anyNA(coeffs))\n             return(2 * r)\n           logeta <- coeffs[1L]\n           if(abs(logeta) <= epsilon)\n             return(0)\n           else\n             return(2 * r)\n         },\n         delta2 = function(X, inte, correction, ..., sparseOK=TRUE) {\n           # Sufficient statistic for second order conditional intensity\n           # Area-interaction model \n           if(!(correction %in% c(\"border\", \"none\")))\n             return(NULL)\n           r <- inte$par$r\n           areadelta2(X, r, sparseOK=sparseOK)\n         },\n       version=NULL # to be added\n  )\n  class(BlankAI) <- \"interact\"\n\n  AreaInter <- function(r) {\n    instantiate.interact(BlankAI, list(r=r))\n  }\n\n  AreaInter <- intermaker(AreaInter, BlankAI)\n  \n  AreaInter\n})"

const rtdal007772Source0002 = `areadelta2 <- local({

  areadelta2 <- function(X, r, ..., sparseOK=TRUE) {
    # Sufficient statistic for second order conditional intensity
    # Area-interaction model 
    if(is.ppp(X)) return(areadelppp(X, r, ..., sparseOK=sparseOK)) else
    if(is.quad(X)) return(areadelquad(X, r, sparseOK=sparseOK)) else
    stop("internal error: X should be a ppp or quad object")
  }

  areadelppp <- function(X, r, algorithm=c("C", "nncross", "nnmap"),
                         sparseOK=TRUE) {
    # Evaluate \Delta_{x_i} \Delta_{x_j} S(x) for data points x_i, x_j
    # i.e.  h(X[i]|X) - h(X[i]|X[-j])
    #       where h is first order cif statistic
    algorithm <- match.arg(algorithm)
    nX <- npoints(X)
    sparseOK <- sparseOK
    result <- if(!sparseOK) matrix(0, nX, nX) else
              sparseMatrix(i=integer(0), j=integer(0), x=numeric(0),
                           dims=c(nX,nX))
    if(nX < 2)
      return(result)
    if(algorithm == "C") {
      # use special purpose C routine
      # called once for each interacting pair of points
      xx <- X$x
      yy <- X$y
      cl <- closepairs(X, 2 * r, what="indices", twice=FALSE, neat=FALSE)
      I <- cl$i
      J <- cl$j
      eps <- r/spatstat.options("ngrid.disc")
      for(k in seq_along(I)) {
        i <- I[k]
        j <- J[k]
        # all neighbours of i
        Ki <- union(J[I==i], I[J==i])
        # all neighbours of j
        Kj <- union(J[I==j], I[J==j])
        # relevant neighbours
        K <- setdiff(union(Ki, Kj), c(i,j))
        # call C code
        z <- .C(SM_delta2area,
                xa = as.double(xx[i]),
                ya = as.double(yy[i]),
                xb = as.double(xx[j]),
                yb = as.double(yy[j]),
                nother = as.integer(length(K)),
                xother = as.double(xx[K]),
                yother = as.double(yy[K]),
                radius = as.double(r),
                epsilon = as.double(eps),
                pixcount = as.integer(integer(1L)),
                PACKAGE="spatstat.model")
        result[i,j] <- result[j,i] <- z$pixcount
      }
      # normalise
      result <- result * (eps^2)/(pi * r^2)
      return(result)
    }

    # non-C algorithms
    # confine attention to points which are interacting
    relevant <- (nndist(X) <= 2 * r)
    if(!all(relevant)) {
      if(any(relevant)) {
        # call self on subset
        Dok <- areadelppp(X[relevant], r, algorithm, sparseOK=sparseOK)
        result[relevant,relevant] <- Dok
      }
      return(result)
    }

    # .............. algorithm using interpreted code ...........
    
    # sort pattern in increasing order of x
    sortX <- (algorithm == "nnmap")
    if(sortX) {
      oX <- fave.order(X$x)
      X <- X[oX]
    }

    # area calculation may be restricted to window W for efficiency
    W <- as.owin(X)
    U <- as.rectangle(W)

    # decide pixel resolution
    eps <- r/spatstat.options("ngrid.disc")
    npix <- prod(ceiling(sidelengths(U)/eps))
    if(npix <= 2^20) {
      # do it all in one go
      tile <- list(NULL)
    } else {
      # divide into rectangular tiles
      B <- as.rectangle(W)
      ntile0 <- ceiling(npix/(2^20))
      tile0area <- area(B)/ntile0
      tile0side <- sqrt(tile0area)
      nx <- ceiling(sidelengths(B)[1L]/tile0side)
      ny <- ceiling(sidelengths(B)[2L]/tile0side)
      tile <- tiles(quadrats(B, nx, ny))
    }
           
    result <- matrix(0, nX, nX)
    for(i in seq_len(length(tile))) {
      # form pixel grid
      Ti <- tile[[i]]
      Wi <- if(is.null(Ti)) W else intersect.owin(W, Ti)
      if(algorithm == "nncross") {
        # Trusted, slow algorithm using nncross
        Z <- as.mask(Wi, eps=eps)
        G <- as.ppp(rasterxy.mask(Z), U, check=FALSE)
        # compute 3 nearest neighbours in X of each grid point
        v <- nncross(G, X, k=1:3)
        # select pixels which have exactly 2 neighbours within distance r
        ok <- with(v, dist.3 > r & dist.2 <= r)
        if(any(ok)) {
          v <- v[ok, , drop=FALSE]
          # accumulate pixel counts -> areas
          counts <- with(v, table(i=factor(which.1, levels=1L:nX),
                                  j=factor(which.2, levels=1L:nX)))
          pixarea <- with(Z, xstep * ystep)
          result <- result + pixarea * (counts + t(counts))
        }
      } else {
        # Faster algorithm using nnmap
        # compute 3 nearest neighbours in X of each grid point
        stuff <- nnmap(X, k=1:3, W=Wi, eps=eps,
                       is.sorted.X=TRUE, sortby="x",
                       outputarray=TRUE)
        dist.2 <- stuff$dist[2L,,]
        dist.3 <- stuff$dist[3L,,]
        which.1 <- stuff$which[1L,,]
        which.2 <- stuff$which[2L,,]
        ok <- (dist.3 > r & dist.2 <= r)
        if(any(ok)) {
          which.1 <- as.vector(which.1[ok])
          which.2 <- as.vector(which.2[ok])
          counts <- table(i=factor(which.1, levels=1L:nX),
                          j=factor(which.2, levels=1L:nX))
          pixarea <- attr(stuff, "pixarea")
          result <- result + pixarea * (counts + t(counts))
        }
      }
    }
    if(sortX) {
      # map back to original ordering
      result[oX, oX] <- result
    }
    # normalise
    result <- result/(pi * r^2)
    return(result)
  }

  areadelquad <- function(Q, r, sparseOK=TRUE) {
    # Sufficient statistic for second order conditional intensity
    # Area-interaction model 
    # Evaluate \Delta_{u_j} \Delta_{u_i} S(x) for quadrature points 
    # answer is area(b(u[i],r) \cap b(u[j],r)\setminus \bigcup_k b(x[k],r))
    # where k ranges over all indices that are not equivalent to u[i,j]
    U <- union.quad(Q)
    Z <- is.data(Q)
    nU <- npoints(U)
    xx <- U$x
    yy <- U$y
    # identify all close pairs of quadrature points
    cl <- closepairs(U, 2 * r, what="indices")
    I <- cl$i
    J <- cl$j
    # find neighbours in X of each quadrature point
    zJ <- Z[J]
    neigh <- split(J[zJ], factor(I[zJ], levels=1L:nU))
    # 
    result <- if(!sparseOK) matrix(0, nU, nU) else
              sparseMatrix(i=integer(0), j=integer(0), x=numeric(0),
                           dims=c(nU,nU))
    eps <- r/spatstat.options("ngrid.disc")
    #
    for(k in seq_along(I)) {
      i <- I[k]
      j <- J[k]
      # all points of X close to U[i]
      Ki <- neigh[[i]]
      # all points of X close to U[j]
      Kj <- neigh[[j]]
      # relevant neighbours
      K <- setdiff(union(Ki, Kj), c(i,j))
      # call C code
      z <- .C(SM_delta2area,
            xa = as.double(xx[i]),
            ya = as.double(yy[i]),
            xb = as.double(xx[j]),
            yb = as.double(yy[j]),
            nother = as.integer(length(K)),
            xother = as.double(xx[K]),
            yother = as.double(yy[K]),
            radius = as.double(r),
            epsilon = as.double(eps),
            pixcount = as.integer(integer(1L)),
            PACKAGE="spatstat.model")
      result[i,j] <- z$pixcount
    }
    # normalise
    result <- result * (eps^2)/(pi * r^2)
    return(result)
  }

  areadelta2
})`

