const rtdal007792Source0002 = `plot.dppm <- function (x, ..., what = c("intensity", "statistic")){
    objectname <- short.deparse(substitute(x))
    if(missing(what) && is.stationary(x))
        what <- "statistic"
    plot.kppm(x, ..., xname = objectname, what = what)
}`

const rtdal007792Source0003 = `Kmodel.dppm <- function (model, ...){
    Kmodel(model$fitted, W=model$window)
}`

const rtdal007792Source0004 = `Lmodel.dppm <- function (model, ...){
    Lmodel(model$fitted, W=model$window)
}`

const rtdal007792Source0005 = `pcfmodel.dppm <- function (model, ...){
    pcfmodel(model$fitted, W=model$window)
}`

const rtdal007792Source0006 = `intensity.dppm <- function (X, ...){
    return(intensity(X$fitted))
}`

const rtdal007792Source0007 = `reach.dppm <- function(x, ...){
    reach(x$fitted, ...)
}`

const rtdal007792Source0010 = `repul <- function(model, ...) {
  UseMethod("repul")
}`

const rtdal007792Source0011 = `repul.dppm <- function(model, ...) {
  g <- pcfmodel(model)
  f <- function(x) { 2 * pi * x * (1 - g(x)) }
  rmax <- reach(model)
  h <- integrate(f, 0, rmax)$value
  lam <- intensity(model)
  ans <- h * lam
  return(ans)
}`

