const rtdal007794Source0001 = `eem <- function(fit, ...) {
  UseMethod("eem")
}`

const rtdal007794Source0002 = `eem.ppm <- function(fit, check=TRUE, ...) {
  verifyclass(fit, "ppm")
  lambda <- fitted.ppm(fit, dataonly=TRUE, check=check)
  eemarks <- 1/lambda
  attr(eemarks, "type") <- "eem"
  attr(eemarks, "typename") <- "exponential energy marks"
  return(eemarks)
}`

const rtdal007794Source0003 = `eem.exactppm <- function(fit, ...) {
  verifyclass(fit, "exactppm")
  ## lambda <- fitted(fit)
  lambda <- predict(fit, locations=fit$X)
  eemarks <- 1/lambda
  attr(eemarks, "type") <- "eem"
  attr(eemarks, "typename") <- "exponential energy marks"
  return(eemarks)
}`

const rtdal007794Source0004 = `eem.slrm <- function(fit, check=TRUE, ...) {
  verifyclass(fit, "slrm")
  Y <- response(fit)
  lambdaY <- predict(fit, type="intensity")[Y, drop=FALSE]
  eemarks <- 1/lambdaY
  attr(eemarks, "type") <- "eem"
  attr(eemarks, "typename") <- "exponential energy marks"
  return(eemarks)
}`

