const rtdal007808Source0001 = "Geyer <- local({\n\n  # .......... template ..........\n\n  BlankGeyer <- \n  list(\n         name     = \"Geyer saturation process\",\n         creator  = \"Geyer\",\n         family   = \"pairsat.family\",  # evaluated later\n         pot      = function(d, par) {\n                         (d <= par$r)  # same as for Strauss\n                    },\n         par      = list(r = NULL, sat=NULL),  # filled in later\n         parnames = c(\"interaction distance\",\"saturation parameter\"),\n         hasInf   = FALSE,\n         init     = function(self) {\n                      r <- self$par$r\n                      sat <- self$par$sat\n                      if(!is.numeric(r) || length(r) != 1 || r <= 0)\n                       stop(\"interaction distance r must be a positive number\")\n                      if(!is.numeric(sat) || length(sat) != 1 || sat < 0)\n                       stop(\"saturation parameter sat must be a positive number\")\n                    },\n         update = NULL, # default OK\n         print = NULL,    # default OK\n         plot = function(fint, ..., d=NULL, plotit=TRUE) {\n           verifyclass(fint, \"fii\")\n           inter <- fint$interaction\n           unitz <- unitname(fint)\n           if(!identical(inter$name, \"Geyer saturation process\"))\n             stop(\"Tried to plot the wrong kind of interaction\")\n           #' fitted interaction coefficient\n           theta <- fint$coefs[fint$Vnames]\n           #' interaction radius\n           r <- inter$par$r\n           sat <- inter$par$sat\n           xlim <- resolve.1.default(list(xlim=c(0, 1.25 * r)), list(...)) \n           rmax <- max(xlim, d)\n           if(is.null(d)) {\n             d <- seq(from=0, to=rmax, length.out=1024)\n           } else {\n             stopifnot(is.numeric(d) &&\n                       all(is.finite(d)) &&\n                       all(diff(d) > 0))\n           }\n           #' compute interaction between two points at distance d\n           y <- exp(theta * sat * (d <= r))\n           #' compute `fv' object\n           fun <- fv(data.frame(r=d, h=y, one=1),\n                     \"r\", substitute(h(r), NULL), \"h\", cbind(h,one) ~ r,\n                     xlim, c(\"r\", \"h(r)\", \"1\"),\n                     c(\"distance argument r\",\n                       \"maximal interaction h(r)\",\n                       \"reference value 1\"),\n                     unitname=unitz)\n           if(plotit)\n             do.call(plot.fv,\n                     resolve.defaults(list(fun),\n                                      list(...),\n                                      list(ylim=range(0,1,y))))\n           return(invisible(fun))\n         },\n         #' end of function 'plot'\n         interpret =  function(coeffs, self) {\n           loggamma <- as.numeric(coeffs[1L])\n           gamma <- exp(loggamma)\n           return(list(param=list(gamma=gamma),\n                       inames=\"interaction parameter gamma\",\n                       printable=dround(gamma)))\n         },\n         valid = function(coeffs, self) {\n           loggamma <- as.numeric(coeffs[1L])\n           sat <- self$par$sat\n           return(is.finite(loggamma) && (is.finite(sat) || loggamma <= 0))\n         },\n         project = function(coeffs, self) {\n           if((self$valid)(coeffs, self)) return(NULL) else return(Poisson())\n         },\n         irange = function(self, coeffs=NA, epsilon=0, ...) {\n           r <- self$par$r\n           if(any(!is.na(coeffs))) {\n             loggamma <- coeffs[1L]\n             if(!is.na(loggamma) && (abs(loggamma) <= epsilon))\n               return(0)\n           }\n           return(2 * r)\n         },\n       version=NULL, # evaluated later\n       # fast evaluation is available for the border correction only\n       can.do.fast=function(X,correction,par) {\n         return(all(correction %in% c(\"border\", \"none\")))\n       },\n       fasteval=function(X,U,EqualPairs,pairpot,potpars,correction,\n                         splitInf=FALSE,\n                         ..., halfway=FALSE, check=TRUE) {\n         #' fast evaluator for Geyer interaction\n         dont.complain.about(splitInf)\n         if(!all(correction %in% c(\"border\", \"none\")))\n           return(NULL)\n         if(spatstat.options(\"fasteval\") == \"test\")\n           message(\"Using fast eval for Geyer\")\n         r   <- potpars$r\n         sat <- potpars$sat\n         # first ensure all data points are in U\n         nX <- npoints(X)\n         nU <- npoints(U)\n         Xseq  <- seq_len(nX)\n         if(length(EqualPairs) == 0) {\n           # no data points currently included \n           missingdata <- rep.int(TRUE, nX)\n         } else {\n           Xused <- EqualPairs[,1L]\n           missingdata <- !(Xseq %in% Xused)\n         }\n         somemissing <- any(missingdata)\n         if(somemissing) {\n           # add the missing data points\n           nmiss <- sum(missingdata)\n           U <- superimpose(U, X[missingdata], W=X$window, check=check)\n           # correspondingly augment the list of equal pairs\n           originalrows <- seq_len(nU)\n           newXindex <- Xseq[missingdata]\n           newUindex <- nU + seq_len(nmiss)\n           EqualPairs <- rbind(EqualPairs, cbind(newXindex, newUindex))\n           nU <- nU + nmiss\n         }\n         # determine saturated pair counts\n         counts <- strausscounts(U, X, r, EqualPairs) \n         satcounts <- pmin.int(sat, counts)\n         satcounts <- matrix(satcounts, ncol=1)\n         if(halfway) {\n           # trapdoor used by suffstat()\n           answer <- satcounts\n         } else if(sat == Inf) {\n           # no saturation: fast code\n           answer <- 2 * satcounts\n         } else {\n           # extract counts for data points\n           Uindex <- EqualPairs[,2L]\n           Xindex <- EqualPairs[,1L]\n           Xcounts <- integer(npoints(X))\n           Xcounts[Xindex] <- counts[Uindex]\n           # evaluate change in saturated counts of other data points\n           change <- geyercounts(U, X, r, sat, Xcounts, EqualPairs)\n           answer <- satcounts + change\n           answer <- matrix(answer, ncol=1)\n         }\n         if(somemissing)\n           answer <- answer[originalrows, , drop=FALSE]\n         return(answer)\n       },\n       delta2 = function(X,inte,correction, ..., sparseOK=TRUE) {\n         # Sufficient statistic for second order conditional intensity\n         # h(X[i] | X) - h(X[i] | X[-j])\n         # Geyer interaction\n         if(correction == \"periodic\") return(NULL)\n         r   <- inte$par$r\n         sat <- inte$par$sat\n         result <- geyerdelta2(X, r, sat,\n                               correction=correction, sparseOK=sparseOK)\n         return(result)\n       }\n  )\n  class(BlankGeyer) <- \"interact\"\n  \n  Geyer <- function(r, sat) {\n    instantiate.interact(BlankGeyer, list(r = r, sat=sat))\n  }\n\n  Geyer <- intermaker(Geyer, BlankGeyer)\n  \n  Geyer\n})"

const rtdal007808Source0003 = `geyerdelta2 <- local({

  geyerdelta2 <- function(X, r, sat, ..., sparseOK=TRUE, correction="none") {
    ## Sufficient statistic for second order conditional intensity
    ## Geyer model
    stopifnot(is.numeric(sat) && length(sat) == 1 && sat > 0)
    ## X could be a ppp or quad.
    if(is.ppp(X)) {
      # evaluate \Delta_{x_i} \Delta_{x_j} S(x) for data points x_i, x_j
      # i.e.  h(X[i]|X) - h(X[i]|X[-j]) where h is first order cif statistic
      return(geydelppp(X, r, sat, correction, sparseOK))
    } else if(is.quad(X)) {
      # evaluate \Delta_{u_i} \Delta_{u_j} S(x) for quadrature points u_i, u_j
      return(geydelquad(X, r, sat, correction, sparseOK))
    } else stop("Internal error: X should be a ppp or quad object")
  }

  geydelppp <- function(X, r, sat, correction, sparseOK) {
    # initialise
    nX <- npoints(X)
    result <- if(!sparseOK) matrix(0, nX, nX) else
              sparseMatrix(i=integer(0), j=integer(0), x=numeric(0),
                           dims=c(nX, nX))
    ## identify all r-close pairs (ordered pairs i ~ j)
    unweighted <- correction %in% c("border", "none")
    if(unweighted) {
      a <- closepairs(X, r, what="indices")
      I <- a$i
      J <- a$j
      IJ <- cbind(I,J)
      ## count number of r-neighbours for each point
      tvals <- table(factor(I, levels=1:nX))
    } else {
      a <- weightedclosepairs(X, r, correction=correction, what="indices")
      I <- a$i
      J <- a$j
      IJ <- cbind(I,J)
      wIJ <- a$weight
      wmatrix <- sparseMatrix(i=I,j=J,x=wIJ, dims=c(nX,nX))
      wJI <- wmatrix[cbind(J,I)]
      ## total edge-correction weight over r-neighbours for each point
      tvals <- tapplysum(wIJ, list(factor(I, levels=1:nX)))
    }
    # Compute direct part
    # (arising when i~j) 
    tI <- tvals[I]
    tJ <- tvals[J]
    if(unweighted) {
      result[IJ] <-
        pmin(sat, tI) - pmin(sat, tI - 1L) + pmin(sat, tJ) - pmin(sat, tJ - 1L)
    } else {
      result[IJ] <-
        pmin(sat, tI) - pmin(sat, tI - wIJ) +
        pmin(sat, tJ) - pmin(sat, tJ - wJI)
    }
    # Compute indirect part
    # (arising when i~k and j~k for another point k)
    # First find all such triples 
    ord <- (I < J)
    vees <- edges2vees(I[ord], J[ord], nX)
    # evaluate contribution of (k, i, j)
    II <- vees$j
    JJ <- vees$k
    KK <- vees$i
    tKK <- tvals[KK]
    if(unweighted) {
      contribKK <- pmin(sat, tKK) - 2 * pmin(sat, tKK-1L) + pmin(sat, tKK-2L)
    } else {
      wKKII <- wmatrix[cbind(KK, II)]
      wKKJJ <- wmatrix[cbind(KK, JJ)]
      contribKK <- (
        pmin(sat, tKK)
        - pmin(sat, tKK-wKKII)
        - pmin(sat, tKK-wKKJJ)
        + pmin(sat, tKK-wKKII-wKKJJ)
      )
    }
    # for each (i, j), sum the contributions over k 
    if(!sparseOK) {
      II <- factor(II, levels=1:nX)
      JJ <- factor(JJ, levels=1:nX)
      # was:
      # delta3 <- tapply(contribKK, list(I=II, J=JJ), sum)
      # delta3[is.na(delta3)] <- 0
      delta3 <- tapplysum(contribKK, list(I=II, J=JJ))
    } else {
      delta3 <- sparseMatrix(i=II, j=JJ, x=contribKK, dims=c(nX, nX))
    }
    # symmetrise and combine
    result <- result + delta3 + t(delta3)
    return(result)
  }

  geydelquad <- function(Q, r, sat, correction, sparseOK) {
    Z <- is.data(Q)
    U <- union.quad(Q)
    nU <- npoints(U)
    nX <- npoints(Q$data)
    result <- if(!sparseOK) matrix(0, nU, nU) else
              sparseMatrix(i=integer(0), j=integer(0), x=numeric(0),
                           dims=c(nU, nU))
    ## identify all r-close pairs U[i], U[j]
    unweighted <- correction %in% c("none", "border")
    if(unweighted) {
      a <- closepairs(U, r, what="indices")
      I <- a$i
      J <- a$j
      IJ <- cbind(I, J)
    } else {
      a <- weightedclosepairs(U, r, correction=correction, what="indices")
      I <- a$i
      J <- a$j
      IJ <- cbind(I, J)
      wIJ <- a$weight
      wmatrix <- sparseMatrix(i=I, j=J, x=wIJ, dims=c(nU,nU))
      wJI <- wmatrix[cbind(J,I)]
    }
    ## tag which ones are data points
    zI <- Z[I]
    zJ <- Z[J]
    # count t(U[i], X)
    IzJ <- I[zJ]
    JzJ <- J[zJ]
    if(unweighted) {
      tvals <- table(factor(IzJ, levels=1:nU))
    } else {
      wzJ <- wIJ[zJ]
      tvals <- tapplysum(wzJ, list(factor(IzJ, levels=1:nU)))
    }
    ## Compute direct part
    ## (arising when U[i]~U[j]) 
    tI <- tvals[I]
    tJ <- tvals[J]
    if(unweighted) {
      tIJ <- tI - zJ
      tJI <- tJ - zI
      result[IJ] <- pmin(sat, tIJ + 1L) - pmin(sat, tIJ) +
                    pmin(sat, tJI + 1L) - pmin(sat, tJI)
    } else {
      tIJ <- tI - zJ * wIJ
      tJI <- tJ - zI * wJI
      result[IJ] <- pmin(sat, tIJ + wIJ) - pmin(sat, tIJ) +
                    pmin(sat, tJI + wJI) - pmin(sat, tJI)
    }
    # Compute indirect part
    # (arising when U[i]~X[k] and U[j]~X[k] for another point X[k])
    # First find all such triples
    # Group close pairs X[k] ~ U[j] by index k
    spl <- split(IzJ, factor(JzJ, levels=1:nX))
    grlen <- lengths(spl)
    # Assemble list of triples U[i], X[k], U[j]
    # by expanding each pair U[i], X[k]
    JJ <- unlist(spl[JzJ])
    II <- rep(IzJ, grlen[JzJ])
    KK <- rep(JzJ, grlen[JzJ])
    # remove identical pairs i = j
    ok <- II != JJ
    II <- II[ok]
    JJ <- JJ[ok]
    KK <- KK[ok]
    # evaluate contribution of each triple
    tKK <- tvals[KK]
    zII <- Z[II]
    zJJ <- Z[JJ]
    if(unweighted) {
      tKIJ <- tKK - zII - zJJ 
      contribKK <-
        pmin(sat, tKIJ + 2L) - 2 * pmin(sat, tKIJ + 1L) + pmin(sat, tKIJ)
    } else {
      wKKII <- wmatrix[cbind(KK, II)]
      wKKJJ <- wmatrix[cbind(KK, JJ)]
      tKIJ <- tKK - zII * wKKII - zJJ * wKKJJ
      contribKK <- (pmin(sat, tKIJ + wKKII + wKKJJ)
        - pmin(sat, tKIJ + wKKII)
        - pmin(sat, tKIJ + wKKJJ)
        + pmin(sat, tKIJ))
    }
    # for each (i, j), sum the contributions over k
    if(!sparseOK) {
      II <- factor(II, levels=1:nU)
      JJ <- factor(JJ, levels=1:nU)
      # was:
      # delta4 <- tapply(contribKK, list(I=II, J=JJ), sum)
      # delta4[is.na(delta4)] <- 0
      delta4 <- tapplysum(contribKK, list(I=II, J=JJ))
    } else {
      delta4 <- sparseMatrix(i=II, j=JJ, x=contribKK, dims=c(nU, nU))
    }
    # combine
    result <- result + delta4
    return(result)
  }

  geyerdelta2
})`

