const rtdal007825Source0002 = `active.interactions <- function(object) {
  stopifnot(inherits(object, "mppm"))
  interaction <- object$Inter$interaction
  iformula <- object$iformula
  nenv <- new.env()
  environment(iformula) <- nenv 
  random <- object$random
  if(!is.null(random))
    environment(random) <- nenv

  itags    <- object$Inter$itags
# The following are currently unused  
#  ninter   <- object$Inter$ninter
#  iused    <- object$Inter$iused
#  trivial  <- object$Inter$trivial

  # names of variables
  dat <- object$data
  datanames <- names(dat)
  dfnames <- summary(dat)$dfnames
  nondfnames <- datanames[!(datanames %in% dfnames)]
  nondfnames <- union(nondfnames, c("x", "y"))
  
  # extract data-frame values
  dfdata <- as.data.frame(dat[, dfnames, drop=FALSE], warn=FALSE)
  
  # determine which interaction(s) are in force 
  answer <- impliedpresence(itags, iformula, dfdata, nondfnames)
  if(!is.null(random)) {
    if("|" %in% all.names(random)) {
      ## hack since model.matrix doesn't handle "|" as desired
      rnd <- gsub("|", "/", pasteFormula(random), fixed=TRUE)
      random <- as.formula(rnd, env=environment(random))
    }
    answer2 <- impliedpresence(itags, random, dfdata, nondfnames)
    answer <- answer | answer2
  }
  colnames(answer) <- names(interaction)
  return(answer)
}`

const rtdal007825Source0003 = `impliedcoefficients <- function(object, tag, new.coef=NULL) {
  stopifnot(inherits(object, "mppm"))
  stopifnot(is.character(tag) && length(tag) == 1)
  fitobj      <- object$Fit$FIT
  Vnamelist   <- object$Fit$Vnamelist
  has.random  <- object$Info$has.random
# Not currently used:  
#  fitter      <- object$Fit$fitter
#  interaction <- object$Inter$interaction
#  ninteract   <- object$Inter$ninteract
#  trivial     <- object$Inter$trivial
#  iused       <- object$Inter$iused
  itags       <- object$Inter$itags
  if(!(tag %in% itags))
    stop(paste("Argument", dQuote("tag"),
               "is not one of the interaction names"))
  # (0) Set up
  # Identify the columns of the glm data frame
  # that are associated with this interpoint interaction 
  vnames <- Vnamelist[[tag]]
  if(!is.character(vnames))
    stop("Internal error - wrong format for vnames")
  # Check atomic type of each covariate
  Moadf <- as.list(object$Fit$moadf)
  islog <- sapply(Moadf, is.logical)
  isnum <- sapply(Moadf, is.numeric)
  isfac <- sapply(Moadf, is.factor)
  # Interaction variables must be numeric or logical
  if(any(bad <- !(isnum | islog)[vnames]))
    stop(paste("Internal error: the",
               ngettext(sum(bad), "variable", "variables"),
               commasep(sQuote(vnames[bad])),
               "should be numeric or logical"),
         call.=FALSE)
  # The answer is a matrix of coefficients,
  # with one row for each point pattern,
  # and one column for each vname
  answer <- matrix(, nrow=object$npat, ncol=length(vnames))
  colnames(answer) <- vnames
  
  # (1) make a data frame of covariates
  # Names of all columns in glm data frame
  allnames <- names(Moadf)
  # Extract the design covariates
  df <- as.data.frame(object$data, warn=FALSE)
  # Names of all covariates other than design covariates
  othernames <- allnames[!(allnames %in% names(df))]
  # Add columns in which all other covariates are set to 0, FALSE, etc
  for(v in othernames) {
    df[, v] <- if(isnum[[v]]) 0 else
               if(islog[[v]]) FALSE else
               if(isfac[[v]]) {
                 lev <- levels(Moadf[[v]])
                 factor(lev[1], levels=lev)
               } else sort(unique(Moadf[[v]]))[1]
  }
  # (2) evaluate linear predictor
  Coefs <- new.coef %orifnull% (if(!has.random) coef(fitobj) else fixef(fitobj))
  suppressWarnings({
#  eta0 <- predict(fitobj, newdata=df, type="link")
    eta0 <- GLMpredict(fitobj, data=df, coefs=Coefs,
                       changecoef=TRUE, type="link")
  })
  
  # (3) for each vname in turn,
  # set the value of the vname to 1 and predict again
  for(j in seq_along(vnames)) {
    vnj <- vnames[j]
    df[[vnj]] <- 1
    suppressWarnings({
#    etaj <- predict(fitobj, newdata=df, type="link")
      etaj <- GLMpredict(fitobj, data=df, coefs=Coefs,
                         changecoef=TRUE, type="link")
    })
    answer[ ,j] <- etaj - eta0
    # set the value of this vname back to 0
    df[[vnj]] <- 0
  }
  return(answer)
}`

const rtdal007825Source0004 = "illegal.iformula <- local({\n\n  illegal.iformula <- function(ifmla, itags, dfvarnames) {\n    ## THIS IS TOO STRINGENT!\n    ## Check validity of the interaction formula.\n    ##  ifmla is the formula.\n    ##  itags is the character vector of interaction names.\n    ## Check whether the occurrences of `itags' in `iformula' are valid:\n    ## e.g. no functions applied to `itags[i]'.\n    ## Returns NULL if legal, otherwise a character string \n    stopifnot(inherits(ifmla, \"formula\"))\n    stopifnot(is.character(itags))\n    ## formula must not have a LHS\n    if(length(ifmla) > 2)\n      return(\"iformula must not have a left-hand side\")\n    ## variables in formula must be interaction tags or data frame variables\n    varsinf <- variablesinformula(ifmla)\n    if(!all(ok <- varsinf %in% c(itags, dfvarnames))) \n      return(paste(\n                   ngettext(sum(!ok), \"variable\", \"variables\"),\n                   paste(dQuote(varsinf[!ok]), collapse=\", \"),\n                   \"not allowed in iformula\"))\n    ## if formula uses no interaction tags, it's trivial\n    if(!any(itags %in% variablesinformula(ifmla)))\n      return(NULL)\n    ## create terms object\n    tt <- attributes(terms(ifmla))\n    ## extract all variables appearing in the formula\n    vars <- as.list(tt$variables)[-1]\n    ##  nvars <- length(vars)\n    varexprs <- lapply(vars, as.expression)\n    varstrings <- sapply(varexprs, paste)\n    ## Each variable may be a name or an expression\n    v.is.name <- sapply(vars, is.name)\n    ## a term may be an expression like sin(x), poly(x,y,degree=2)\n    v.args <- lapply(varexprs, all.vars)\n    ##  v.n.args <- sapply(v.args, length)\n    v.has.itag <- sapply(lapply(v.args, \"%in%\", x=itags), any)\n    ## interaction tags may only appear as names, not in functions\n    if(any(nbg <- v.has.itag & !v.is.name))\n      return(paste(\"interaction tags may not appear inside a function:\",\n                   paste(dQuote(varstrings[nbg]), collapse=\", \")))\n    ## Interaction between two itags is not defined\n    ## Inspect the higher-order terms\n    fax <- tt$factors\n    if(prod(dim(fax)) == 0)\n      return(NULL)\n    ## rows are first order terms, columns are terms of order >= 1\n    fvars <- rownames(fax)\n    fterms <- colnames(fax)\n    fv.args <- lapply(fvars, variablesintext)\n    ft.args <- lapply(fterms, variables.in.term, \n                      factors=fax, varnamelist=fv.args)\n    ft.itags <- lapply(ft.args, intersect, y=itags)\n    if(any(lengths(ft.itags) > 1))\n      return(\"Interaction between itags is not defined\")\n    return(NULL)\n  }\n\n  variables.in.term <- function(term, factors, varnamelist) {\n    basis <- (factors[, term] != 0)\n    unlist(varnamelist[basis])\n  }\n  \n  illegal.iformula\n})"

