const rtdal007830Source0019 = `as.fv.kppm <- as.fv.dppm <- function(x) {
  if(x$Fit$method == "mincon") 
    return(as.fv(x$Fit$mcfit))
  gobs <- if(is.stationary(x)) {
            pcf(x$X,
                correction="good", divisor="a", zerocor="J")
          } else {
            pcfinhom(x$X,
                     lambda=x, update=FALSE,
                     correction="good", divisor="a", zerocor="J")
          }
  gname <- attr(gobs, "fname")
  gfit <- (pcfmodel(x))(gobs$r)
  g <- bind.fv(gobs,
               data.frame(fit=gfit),
               labl = makefvlabel(fname=gname, sub="fit"),
               desc = "predicted %s for fitted model")
  return(g)
}`

const rtdal007830Source0020 = `coef.kppm <- coef.dppm <- function(object, ...) {
  return(coef(object$po))
}`

const rtdal007830Source0021 = `Kmodel.kppm <- function(model, ...) {
  Kpcf.kppm(model, what="K")
}`

const rtdal007830Source0022 = `Lmodel.kppm <- function(model, ...) {
  Kfun <- Kpcf.kppm(model, what="K")
  Lfun <- function(r) { sqrt(Kfun(r)/pi) }
  return(Lfun)
}`

const rtdal007830Source0023 = `pcfmodel.kppm <- function(model, ...) {
  Kpcf.kppm(model, what="pcf")
}`

const rtdal007830Source0025 = `is.stationary.kppm <- is.stationary.dppm <- function(x) {
  return(x$stationary)
}`

const rtdal007830Source0026 = `is.poisson.kppm <- function(x) {
  switch(x$clusters,
         Cauchy=,
         VarGamma=,
         Thomas=,
         MatClust={
           # Poisson cluster process
           mu <- x$mu
           return(!is.null(mu) && (max(mu) == 0))
         },
         LGCP = {
           # log-Gaussian Cox process
           sigma2 <- x$par[["sigma2"]]
           return(sigma2 == 0)
         },
         return(FALSE))
}`

const rtdal007830Source0027 = `as.ppm.kppm <- as.ppm.dppm <- function(object) {
  object$po
}`

const rtdal007830Source0028 = `as.owin.kppm <- as.owin.dppm <- function(W, ..., from=c("points", "covariates"), fatal=TRUE) {
  from <- match.arg(from)
  as.owin(as.ppm(W), ..., from=from, fatal=fatal)
}`

const rtdal007830Source0029 = `domain.kppm <- Window.kppm <- domain.dppm <-
  Window.dppm <- function(X, ..., from=c("points", "covariates")) {
  from <- match.arg(from)
  as.owin(X, from=from)
}`

const rtdal007830Source0030 = `model.images.kppm <-
  model.images.dppm <- function(object, W=as.owin(object), ...) {
  model.images(as.ppm(object), W=W, ...)
}`

const rtdal007830Source0031 = `model.matrix.kppm <-
  model.matrix.dppm <- function(object,
                                data=model.frame(object, na.action=NULL), ...,
                                Q=NULL, 
                                keepNA=TRUE) {
  if(missing(data)) data <- NULL
  model.matrix(as.ppm(object), data=data, ..., Q=Q, keepNA=keepNA)
}`

const rtdal007830Source0032 = `model.frame.kppm <- model.frame.dppm <- function(formula, ...) {
  model.frame(as.ppm(formula), ...)
}`

const rtdal007830Source0033 = `logLik.kppm <- logLik.dppm <- function(object, ...) {
  cl <- object$Fit$maxlogcl
  if(is.null(cl))
    stop(paste("logLik is only available for kppm objects fitted with",
               "method='palm' or method='clik2'"),
         call.=FALSE)
  ll <- logLik(as.ppm(object)) # to inherit class and d.f.
  ll[] <- cl
  return(ll)
}`

const rtdal007830Source0034 = `AIC.kppm <- AIC.dppm <- function(object, ..., k=2) {
  cl <- logLik(object)
  df <- attr(cl, "df")
  return(- 2 * as.numeric(cl) + k * df)
}`

const rtdal007830Source0035 = `extractAIC.kppm <- extractAIC.dppm <- function (fit, scale = 0, k = 2, ...) {
  cl <- logLik(fit)
  edf <- attr(cl, "df")
  aic <- - 2 * as.numeric(cl) + k * edf
  return(c(edf, aic))
}`

const rtdal007830Source0036 = `nobs.kppm <- nobs.dppm <- function(object, ...) { nobs(as.ppm(object)) }`

const rtdal007830Source0039 = `reach.kppm <- function(x, ..., epsilon) {
  thresh <- if(missing(epsilon)) NULL else epsilon
  if(x$isPCP) 
    return(2 * clusterradius.kppm(x, ..., thresh=thresh))
  ## use pair correlation
  g <- pcfmodel(x)
  ## find upper bound
  if(is.null(thresh)) thresh <- 0.01
  f <- function(r) { g(r) - 1 - thresh }
  scal <- as.list(x$par)$scale %orifnull% 1
  for(a in scal * 2^(0:10)) { if(f(a) < 0) break; }
  if(f(a) > 0) return(Inf)
  ## solve g(r) = 1 + epsilon
  b <- uniroot(f, c(0, a))$root
  return(b)
}`

const rtdal007830Source0045 = `repul.kppm <- function(model, ...) {
  if(isTRUE(model$isPCP) && !is.null(mu <- model$mu)) {
    return(-mu)
  }
  g <- pcfmodel(model)
  f <- function(x) { 2 * pi * x * (1 - g(x)) }
  rmax <- reach(model)
  h <- integrate(f, 0, rmax)$value
  lam <- intensity(model)
  ans <- h * lam
  return(ans)
}`

const rtdal007830Source0046 = `repul.clusterprocess <- function(model, ...) {
  g <- pcfmodel(model)
  f <- function(x) { 2 * pi * x * (1 - g(x)) }
  rmax <- reach(model)
  h <- integrate(f, 0, rmax)$value
  lam <- intensity(model)
  ans <- h * lam
  return(ans)
}`

