const rtdal007846Source0001 = "mpl.engine <- \n  function(Q,\n           trend = ~1,\n           interaction = NULL,\n           ...,\n           covariates = NULL,\n           subsetexpr = NULL,\n           clipwin = NULL,\n           covfunargs = list(),\n           correction=\"border\",\n           rbord = 0,\n           use.gam=FALSE,\n           gcontrol=list(),\n           GLM=NULL,\n           GLMfamily=NULL,\n           GLMcontrol=NULL,\n           famille=NULL,\n           forcefit=FALSE,\n           nd = NULL,\n           eps = NULL,\n           quad.args = list(),\n           allcovar=FALSE,\n           callstring=\"\",\n           precomputed=NULL,\n           savecomputed=FALSE,\n           preponly=FALSE,\n           rename.intercept=TRUE,\n           justQ = FALSE,\n           weightfactor = NULL,\n           Xweights=1\n ) {\n    GLMname <- if(!missing(GLM)) short.deparse(substitute(GLM)) else NULL\n    ## Extract precomputed data if available\n    if(!is.null(precomputed$Q)) {\n      Q <- precomputed$Q\n      X <- precomputed$X\n      P <- precomputed$U\n    } else {\n      ## Determine quadrature scheme from argument Q\n      if(verifyclass(Q, \"quad\", fatal=FALSE)) {\n        ## user-supplied quadrature scheme - validate it\n        validate.quad(Q, fatal=TRUE, repair=FALSE, announce=TRUE)\n        ## Extract data points\n        X <- Q$data\n      } else if(verifyclass(Q, \"ppp\", fatal = FALSE)) {\n        ## point pattern - create quadrature scheme\n        X <- Q\n        if(!is.null(nd)) quad.args$nd <- nd\n        if(!is.null(eps)) quad.args$eps <- eps\n        Q <- do.call(quadscheme, append(list(data=quote(X), check=FALSE), quad.args))\n      } else \n      stop(\"First argument Q should be a point pattern or a quadrature scheme\")\n      ## Data and dummy points together\n      P <- union.quad(Q)\n    }\n    ## clip to subset?\n    if(!is.null(clipwin)) {\n      if(is.data.frame(covariates)) \n        covariates <- covariates[inside.owin(P, w=clipwin), , drop=FALSE]\n      #' catch information used by 'linequad'\n      situ <- attr(Q, \"situ\")\n      Q <- Q[clipwin]\n      X <- X[clipwin]\n      P <- P[clipwin]\n      if(!is.null(situ))\n        attr(Q, \"situ\") <- situ[clipwin]\n    }\n    ## secret exit  \n    if(justQ) return(Q)\n    ##  \n    computed <- if(savecomputed) list(X=X, Q=Q, U=P) else NULL\n    ##\n    ## Validate main arguments\n    if(!is.null(trend) && !inherits(trend, \"formula\"))\n      stop(paste(\"Argument\", sQuote(\"trend\"), \"must be a formula\"))\n    if(!is.null(interaction) && !inherits(interaction, \"interact\"))\n      stop(paste(\"Argument\", sQuote(\"interaction\"), \"has incorrect format\"))\n    ##\n    check.1.real(rbord, \"In ppm\")\n    explain.ifnot(rbord >= 0, \"In ppm\")\n    ## rbord applies only to border correction\n    if(correction != \"border\") rbord <- 0 \n    ##\n    covfunargs <- as.list(covfunargs)\n    ##\n    ## Interpret the call\n    if(is.null(trend)) {\n      trend <- ~1\n      environment(trend) <- parent.frame()\n      want.trend <- FALSE\n    } else {\n      want.trend <- !identical.formulae(trend, ~1)\n    }\n    want.inter <- !is.null(interaction) && !is.null(interaction$family)\n\n    ## environment (should only be needed to find functions)\n    env.trend <- environment(trend)\n    \n    ## Stamp with spatstat version number\n    spv <- package_version(versionstring.spatstat())\n    the.version <- list(major=spv$major,\n                        minor=spv$minor,\n                        release=spv$patchlevel,\n                        date=\"$Date: 2026/01/21 06:26:39 $\")\n\n    if(want.inter) {\n      ## ensure we're using the latest version of the interaction object\n      if(outdated.interact(interaction)) \n        interaction <- update(interaction)\n    }\n\n    ##  \n  \n    if(!want.trend && !want.inter &&\n       !forcefit && !allcovar && is.null(subsetexpr)) {\n      ## the model is the uniform Poisson process\n      ## The MPLE (= MLE) can be evaluated directly\n      nX <- npoints(X)\n      if(!missing(Xweights))\n        check.nvector(Xweights, nX, oneok=TRUE, vname=\"Xweights\")\n      W  <- as.owin(X)\n      if(correction == \"border\" && rbord > 0) {\n        ## npts <- sum(bdist.points(X) >= rbord)\n        npts <- sum(Xweights * (bdist.points(X) >= rbord))\n        areaW <- eroded.areas(W, rbord)\n      } else {\n        ## npts <- npoints(X)\n        npts <- if(length(Xweights) == 1) Xweights * nX else sum(Xweights)\n        areaW <- area(W)\n      }\n      volume <- areaW * markspace.integral(X)\n      lambda <- npts/volume\n      ## fitted canonical coefficient\n      co <- log(lambda)\n      ## asymptotic variance of canonical coefficient\n      varcov <- matrix(1/npts, 1, 1)\n      fisher <- matrix(npts,   1, 1)\n      se <- sqrt(1/npts)\n      ## give names\n      tag <- if(rename.intercept) \"log(lambda)\" else \"(Intercept)\"\n      names(co) <- tag\n      dimnames(varcov) <- dimnames(fisher) <- list(tag, tag)\n      ## maximised log likelihood\n      maxlogpl <- if(npts == 0) 0 else npts * (log(lambda) - 1)\n      ##\n      rslt <- list(\n                   method      = \"mpl\",\n                   fitter      = \"exact\",\n                   projected   = FALSE,\n                   coef        = co,\n                   trend       = trend,\n                   interaction = NULL,\n                   fitin       = fii(),\n                   Q           = Q,\n                   maxlogpl    = maxlogpl,\n                   satlogpl    = NULL,\n                   internal    = list(computed=computed, se=se),\n                   covariates  = mpl.usable(covariates),\n                                        ## covariates are still retained!\n                   covfunargs  = covfunargs,\n                   subsetexpr  = NULL,\n                   correction  = correction,\n                   rbord       = rbord,\n                   terms       = terms(trend),\n                   fisher      = fisher,\n                   varcov      = varcov,\n                   version     = the.version,\n                   problems    = list(),\n                   Xweights    = Xweights\n                   )\n      class(rslt) <- \"ppm\"\n      return(rslt)\n    }\n    #################  P r e p a r e    D a t a   ######################\n\n    prep <- mpl.prepare(Q, X, P, trend, interaction,\n                        covariates, \n                        want.trend, want.inter, correction, rbord,\n                        \"quadrature points\", callstring,\n                        subsetexpr=subsetexpr,\n                        allcovar=allcovar,\n                        precomputed=precomputed, savecomputed=savecomputed,\n                        covfunargs=covfunargs,\n                        weightfactor=weightfactor,\n                        Xweights=Xweights,\n                        ...)\n    ## back door\n    if(preponly) {\n      ## exit now, returning prepared data frame and internal information\n      prep$info <- list(want.trend=want.trend,\n                        want.inter=want.inter,\n                        correction=correction,\n                        rbord=rbord,\n                        interaction=interaction)\n      return(prep)\n    }\n  \n  \n    fmla <- prep$fmla\n    glmdata <- prep$glmdata\n    problems <- prep$problems\n    likelihood.is.zero <- prep$likelihood.is.zero\n    is.identifiable <- prep$is.identifiable\n    computed <- resolve.defaults(prep$computed, computed)\n    IsOffset <- prep$IsOffset\n\n    ## update covariates (if they were resolved from the environment)  \n    if(!is.null(prep$covariates))\n      covariates <- prep$covariates\n  \n    ################# F i t    i t   ####################################\n\n    if(!is.identifiable) \n      stop(paste(\"in\", callstring, \":\", problems$unidentifiable$print),\n           call.=FALSE)\n  \n    ## to avoid problem with package checker  \n    .mpl.W <- glmdata$.mpl.W\n    .mpl.SUBSET <- glmdata$.mpl.SUBSET\n\n    ## determine algorithm control parameters\n    if(is.null(gcontrol)) gcontrol <- list() else stopifnot(is.list(gcontrol))\n    gcontrol <- if(!is.null(GLMcontrol)) do.call(GLMcontrol, gcontrol) else\n                if(want.trend && use.gam) do.call(mgcv::gam.control, gcontrol) else\n                do.call(stats::glm.control, gcontrol)\n  \n    ## Fit the generalized linear/additive model.\n\n    if(is.null(GLM) && is.null(famille)) {\n      ## the sanctioned technique, using `quasi' family\n      if(want.trend && use.gam) {\n        FIT  <- gam(fmla, family=quasi(link=\"log\", variance=\"mu\"),\n                    weights=.mpl.W,\n                    data=glmdata, subset=.mpl.SUBSET,\n                    control=gcontrol)\n        fittername <- \"gam\"\n      } else {\n        FIT  <- glm(fmla, family=quasi(link=\"log\", variance=\"mu\"),\n                    weights=.mpl.W,\n                    data=glmdata, subset=.mpl.SUBSET,\n                    control=gcontrol, model=FALSE)\n        fittername <- \"glm\"\n      }\n    } else if(!is.null(GLM)) {\n      ## alternative GLM fitting function or penalised GLM etc\n      fam <- GLMfamily %orifnull% quasi(link=\"log\", variance=\"mu\")\n      FIT <- GLM(fmla, family=fam,\n                 weights=.mpl.W,\n                 data=glmdata, subset=.mpl.SUBSET,\n                 control=gcontrol)\n      fittername <- GLMname\n    } else {\n      ## experimentation only!\n      if(is.function(famille))\n        famille <- famille()\n      stopifnot(inherits(famille, \"family\"))\n      if(want.trend && use.gam) {\n        FIT  <- gam(fmla, family=famille, weights=.mpl.W,\n                    data=glmdata, subset=.mpl.SUBSET,\n                    control=gcontrol)\n        fittername <- \"experimental\"\n      } else {\n        FIT  <- glm(fmla, family=famille, weights=.mpl.W,\n                    data=glmdata, subset=.mpl.SUBSET,\n                    control=gcontrol, model=FALSE)\n        fittername <- \"experimental\"\n      }\n    }\n    environment(FIT$terms) <- sys.frame(sys.nframe())\n\n  \n    ################  I n t e r p r e t    f i t   #######################\n\n    ## Fitted coefficients\n    co <- FIT$coef\n\n    ## glm covariates\n    W <- glmdata$.mpl.W\n    SUBSET <- glmdata$.mpl.SUBSET        \n    Z <- is.data(Q)\n    Vnames <- prep$Vnames\n    vnameprefix <- prep$vnameprefix\n\n    ## saturated log pseudolikelihood\n    satlogpl <- - (sum(log(W[Z & SUBSET])) + sum(Z & SUBSET))\n    ## attained value of max log pseudolikelihood\n    maxlogpl <- if(likelihood.is.zero) -Inf else (satlogpl - deviance(FIT)/2)\n\n    ## fitted interaction object\n    fitin <- if(want.inter) {\n               fii(interaction, co, Vnames, IsOffset, vnameprefix)\n             } else fii()\n    unitname(fitin) <- unitname(X)\n    ######################################################################\n    ## Clean up & return \n\n    rslt <-\n      list(\n           method       = \"mpl\",\n           fitter       = fittername,\n           projected    = FALSE,\n           coef         = co,\n           trend        = trend,\n           interaction  = if(want.inter) interaction else NULL,\n           fitin        = fitin,\n           Q            = Q,\n           maxlogpl     = maxlogpl,\n           satlogpl     = satlogpl,\n           internal     = list(glmfit=FIT, glmdata=glmdata, Vnames=Vnames,\n                               IsOffset=IsOffset, fmla=fmla, computed=computed,\n                               vnamebase=prep$vnamebase,\n                               vnameprefix=prep$vnameprefix),\n           covariates   = mpl.usable(covariates),\n           covfunargs   = covfunargs,\n           subsetexpr   = subsetexpr,\n           correction   = correction,\n           rbord        = rbord,\n           terms        = terms(trend),\n           version      = the.version,\n           problems     = problems,\n           Xweights     = Xweights\n        )\n    class(rslt) <- \"ppm\"\n    return(rslt)\n  }"

const rtdal007846Source0002 = "mpl.prepare <- local({\n\n  mpl.prepare <- function(Q, X, P, trend, interaction, covariates, \n                          want.trend, want.inter, correction, rbord,\n                          Pname=\"quadrature points\", callstring=\"\",\n                          ...,\n                          subsetexpr=NULL,\n                          covfunargs=list(),\n                          allcovar=FALSE,\n                          precomputed=NULL, savecomputed=FALSE,\n                          vnamebase=c(\"Interaction\", \"Interact.\"),\n                          vnameprefix=NULL,\n                          warn.illegal=TRUE,\n                          warn.unidentifiable=TRUE,\n                          weightfactor=NULL,\n                          skip.border=FALSE,\n                          clip.interaction=TRUE,\n                          splitInf=FALSE,\n                          Xweights=1) {\n    ## Q: quadrature scheme\n    ## X = data.quad(Q)\n    ## P = union.quad(Q)\n\n    if(missing(want.trend))\n      want.trend <- !is.null(trend) && !identical.formulae(trend, ~1)\n    if(missing(want.inter))\n      want.inter <- !is.null(interaction) && !is.null(interaction$family)\n\n    want.subset <- !is.null(subsetexpr)\n  \n    if(!missing(Xweights)) {\n      if(is.null(Xweights)) {\n        Xweights <- 1\n      } else {\n        check.nvector(Xweights, X$n, things=\"data points\",\n                      vname=\"Xweights\", oneok=TRUE)\n      }\n    }\n\n    #' reserved names for coordinates\n    reserved.vars <- c(\"x\", \"y\", if(is.marked(Q)) \"marks\" else NULL)\n    #' add local coordinates e.g. in linear network\n    if(has.insitu <- !is.null(situ <- attr(Q, \"situ\"))) \n      reserved.vars <- union(reserved.vars, names(coords(situ)))\n    \n    computed <- list()\n    problems <- list()\n  \n    names.precomputed <- names(precomputed)\n\n    likelihood.is.zero <- FALSE\n    is.identifiable <- TRUE\n  \n    if(!missing(vnamebase)) {\n      if(length(vnamebase) == 1)\n        vnamebase <- rep.int(vnamebase, 2)\n      if(!is.character(vnamebase) || length(vnamebase) != 2)\n        stop(\"Internal error: illegal format of vnamebase\")\n    }\n    if(!is.null(vnameprefix)) {\n      if(!is.character(vnameprefix) || length(vnameprefix) != 1)\n        stop(\"Internal error: illegal format of vnameprefix\")\n    }\n      \n    ################ C o m p u t e     d a t a  ####################\n\n    ## Extract covariate values\n    updatecovariates <- FALSE\n    covariates.df <- NULL\n    if(allcovar || want.trend || want.subset) {\n      if(\"covariates.df\" %in% names.precomputed) {\n        covariates.df <- precomputed$covariates.df\n      } else {\n        if(!is.data.frame(covariates)) {\n          ## names of 'external' covariates to be found\n          covnames <- variablesinformula(trend)\n          if(want.subset)\n            covnames <- union(covnames, all.vars(subsetexpr))\n          if(allcovar)\n            covnames <- union(covnames, names(covariates))\n          covnames <- setdiff(covnames, reserved.vars)\n          ## resolve 'external' covariates\n          tenv <- environment(trend)\n          covariates <- getdataobjects(covnames, tenv, covariates, fatal=TRUE)\n          updatecovariates <- any(attr(covariates, \"external\"))\n        }\n        ## extract values of covariates ('internal' and 'external')\n        covariates.df <- mpl.get.covariates(covariates, P, Pname, covfunargs)\n      }\n      if(savecomputed)\n        computed$covariates.df <- covariates.df\n    } \n\n    ## Form the weights and the ``response variable''.\n\n    if(\"dotmplbase\" %in% names.precomputed) {\n      .mpl <- precomputed$dotmplbase\n      if(is.marked(Q) && is.null(.mpl$MARKS))\n        stop(\"Internal error: mark values are missing from precomputed data\",\n             call.=FALSE)\n    } else {\n      nQ <- n.quad(Q)\n      wQ <- w.quad(Q)\n      mQ <- marks.quad(Q)   ## is NULL for unmarked patterns\n      zQ <- is.data(Q)\n      yQ <- numeric(nQ)\n      yQ[zQ] <- Xweights/wQ[zQ]\n      zeroes <- attr(wQ, \"zeroes\")\n      sQ <- if(is.null(zeroes)) rep.int(TRUE, nQ) else !zeroes\n      ## tweak weights ONLY\n      if(!is.null(weightfactor))\n        wQ <- wQ * weightfactor\n      ## pack up\n      .mpl <- list(W      = wQ,\n                   Z      = zQ,\n                   Y      = yQ,\n                   MARKS  = mQ, \n                   SUBSET = sQ)\n    }\n\n    \n    if(savecomputed)\n      computed$dotmplbase <- .mpl\n  \n    glmdata <- data.frame(.mpl.W = .mpl$W,\n                          .mpl.Y = .mpl$Y)\n\n    ## count data and dummy points in specified subset\n    izdat <- .mpl$Z[.mpl$SUBSET]\n    ndata <- sum(izdat)\n#    ndummy <- sum(!izdat)\n    \n    ## Determine the domain of integration for the pseudolikelihood.\n    if(correction == \"border\") {\n      bdP <-\n        if(\"bdP\" %in% names.precomputed)\n          precomputed$bdP\n        else\n          bdist.points(P)\n      if(savecomputed)\n        computed$bdP <- bdP\n      .mpl$DOMAIN <- (bdP >= rbord)\n    }\n\n    skip.border <- skip.border && (correction == \"border\")\n  \n    ####################### T r e n d ##############################\n\n    internal.names <- c(\".mpl.W\", \".mpl.Y\", \".mpl.Z\", \".mpl.SUBSET\",\n                        \"SUBSET\", \".mpl\")\n\n    reserved.names <- c(reserved.vars, internal.names)\n\n    if(allcovar || want.trend || want.subset) {\n      trendvariables <- variablesinformula(trend)\n      ## Check for use of internal names in trend\n      cc <- check.clashes(internal.names, trendvariables, \"the model formula\")\n      if(cc != \"\") stop(cc)\n      if(want.subset) {\n        subsetvariables <- all.vars(subsetexpr)\n        cc <- check.clashes(internal.names, trendvariables,\n                            \"the subset expression\")\n        if(cc != \"\") stop(cc)\n        trendvariables <- union(trendvariables, subsetvariables)\n      }\n      if(\"marks\" %in% trendvariables && !is.marked(Q))\n        stop(\"Model formula involves marks, but data are not marked\",\n             call.=FALSE)\n      ## Add reserved variables?\n      reqd <- if(allcovar) reserved.vars else\n              intersect(reserved.vars, trendvariables)\n      if(length(reqd)) {\n        avail <- list(x = P$x,\n                      y = P$y,\n                      marks = .mpl$MARKS)\n        if(has.insitu) {\n          avail <- resolve.defaults(as.list(coords(situ)),\n                                    avail)\n        }\n        glmdata <- cbind(glmdata,\n                         as.data.frame(avail[reqd]))\n      }\n      ##\n      ## Check covariates\n      if(!is.null(covariates.df)) {\n        ## Check for duplication of reserved names\n        cc <- check.clashes(reserved.names, names(covariates),\n                            sQuote(\"covariates\"))\n        if(cc != \"\") stop(cc)\n        ## Take only those covariates that are named in the trend formula\n        if(!allcovar) \n          needed <- names(covariates.df) %in% trendvariables\n        else\n          needed <- rep.int(TRUE, ncol(covariates.df))\n        if(any(needed)) {\n          covariates.needed <- covariates.df[, needed, drop=FALSE]\n          ##  Append to `glmdata'\n          glmdata <- data.frame(glmdata,covariates.needed)\n          ##  Ignore any quadrature points that have NA's in the covariates\n          nbg <- is.na(covariates.needed)\n          if(any(nbg)) {\n            offending <- matcolany(nbg)\n            covnames.na <- names(covariates.needed)[offending]\n            quadpoints.na <- matrowany(nbg)\n            n.na <- sum(quadpoints.na)\n            n.tot <- length(quadpoints.na)\n            errate <- n.na/n.tot\n            pcerror <- round(signif(100 * errate, 2), 2)\n            complaint <- paste(\"Values of the\",\n                               ngettext(length(covnames.na),\n                                        \"covariate\", \"covariates\"),\n                               paste(sQuote(covnames.na), collapse=\", \"),\n                               \"were NA or undefined at\",\n                               paste(pcerror, \"%\",\n                                     \" (\", \n                                     n.na,\n                                     \" out of \",\n                                     n.tot,\n                                     \")\",\n                                     sep=\"\"),\n                               \"of the\", Pname)\n            warning(paste(complaint,\n                          \". Occurred while executing: \",\n                          callstring, sep=\"\"),\n                    call. = FALSE)\n            .mpl$SUBSET <-  .mpl$SUBSET & !quadpoints.na\n            details <- list(covnames.na   = covnames.na,\n                            quadpoints.na = quadpoints.na,\n                            print         = complaint)\n            problems <- append(problems,\n                               list(na.covariates=details))\n          }\n        }\n      }\n    }\n\n    ###################### I n t e r a c t i o n ####################\n\n    Vnames <- NULL\n    IsOffset <- NULL\n    forbid <- NULL\n    \n    if(want.inter) {\n      ## Form the matrix of \"regression variables\" V.\n      ## The rows of V correspond to the rows of P (quadrature points)\n      ## while the column(s) of V are the regression variables (log-potentials)\n\n      E <- precomputed$E %orifnull% equalpairs.quad(Q)\n\n      if(!skip.border) {\n        ## usual case\n        V <- evalInteraction(X, P, E, interaction, correction,\n                             ...,\n                             splitInf=splitInf,\n                             precomputed=precomputed,\n                             savecomputed=savecomputed)\n      } else {\n        ## evaluate only in eroded domain\n        if(all(c(\"Esub\", \"Usub\", \"Retain\") %in% names.precomputed)) {\n          ## use precomputed data\n          Psub <- precomputed$Usub\n          Esub <- precomputed$Esub\n          Retain <- precomputed$Retain\n        } else {\n          ## extract subset of quadrature points\n          Retain <- .mpl$DOMAIN | is.data(Q)\n          Psub <- P[Retain]\n          ## map serial numbers in P to serial numbers in Psub\n          Pmap <- cumsum(Retain)\n          ## extract subset of equal-pairs matrix\n          keepE <- Retain[ E[,2] ]\n          Esub <- E[ keepE, , drop=FALSE]\n          ## adjust indices in equal pairs matrix\n          Esub[,2] <- Pmap[Esub[,2]]\n        }\n        ## call evaluator on reduced data\n        if(all(c(\"X\", \"Q\", \"U\") %in% names.precomputed)) {\n          subcomputed <- resolve.defaults(list(E=Esub, U=Psub, Q=Q[Retain]),\n                                          precomputed)\n        } else subcomputed <- NULL\n        if(clip.interaction) {\n          ## normal\n          V <- evalInteraction(X, Psub, Esub, interaction, correction,\n                               ...,\n                               splitInf=splitInf,\n                               precomputed=subcomputed,\n                               savecomputed=savecomputed)\n        } else {\n          ## ignore window when calculating interaction\n          ## by setting 'W=NULL' (currently detected only by AreaInter)\n          V <- evalInteraction(X, Psub, Esub, interaction, correction,\n                               ...,\n                               W=NULL,\n                               splitInf=splitInf,\n                               precomputed=subcomputed,\n                               savecomputed=savecomputed)\n        }\n        if(savecomputed) {\n          computed$Usub <- Psub\n          computed$Esub <- Esub\n          computed$Retain <- Retain\n        }\n      }\n      \n      if(!is.matrix(V))\n        stop(\"interaction evaluator did not return a matrix\")\n      \n      ## extract information about offsets\n      IsOffset <- attr(V, \"IsOffset\")\n      if(is.null(IsOffset)) IsOffset <- FALSE\n\n      if(splitInf) {\n        ## extract information about hard core terms\n        forbid <- attr(V, \"-Inf\") %orifnull% logical(nrow(V))\n      } \n\n      if(skip.border) {\n        ## fill in the values in the border region with zeroes.\n        Vnew <- matrix(0, nrow=npoints(P), ncol=ncol(V))\n        colnames(Vnew) <- colnames(V)\n        Vnew[Retain, ] <- V\n        ## retain attributes\n        attr(Vnew, \"IsOffset\") <- IsOffset\n        attr(Vnew, \"computed\") <- attr(V, \"computed\")\n        attr(Vnew, \"POT\") <- attr(V, \"POT\")\n        V <- Vnew\n        if(splitInf) {\n          fnew <- logical(nrow(Vnew))\n          fnew[Retain] <- forbid\n          forbid <- fnew\n        }\n      }\n    \n      ## extract intermediate computation results \n      if(savecomputed)\n        computed <- resolve.defaults(attr(V, \"computed\"), computed)\n\n      ## Augment data frame by appending the regression variables\n      ## for interactions.\n      ##\n      ## First determine the names of the variables\n      ##\n      Vnames <- dimnames(V)[[2]]\n      if(is.null(Vnames)) {\n        ## No names were provided for the columns of V.\n        ## Give them default names.\n        ## In ppm the names will be \"Interaction\"\n        ##   or \"Interact.1\", \"Interact.2\", ...\n        ## In mppm an alternative tag will be specified by vnamebase.\n        nc <- ncol(V)\n        Vnames <- if(nc == 1) vnamebase[1] else paste0(vnamebase[2], 1:nc)\n        dimnames(V) <- list(dimnames(V)[[1]], Vnames)\n      } else if(!is.null(vnameprefix)) {\n        ## Variable names were provided by the evaluator (e.g. MultiStrauss).\n        ## Prefix the variable names by a string\n        ## (typically required by mppm)\n        Vnames <- paste(vnameprefix, Vnames, sep=\"\")\n        dimnames(V) <- list(dimnames(V)[[1]], Vnames)\n      }\n      \n      ## Check the names are valid as column names in a dataframe\n      okVnames <- make.names(Vnames, unique=TRUE)\n      if(any(Vnames != okVnames)) {\n        warning(paste(\"Names of interaction terms\",\n                      \"contained illegal characters;\",\n                      \"names have been repaired.\"))\n        Vnames <- okVnames\n      }\n    \n      ##   Check for name clashes between the interaction variables\n      ##   and the formula\n      cc <- check.clashes(Vnames, termsinformula(trend), \"model formula\")\n      if(cc != \"\") stop(cc)\n      ##   and with the variables in 'covariates'\n      if(!is.null(covariates)) {\n        cc <- check.clashes(Vnames, names(covariates), sQuote(\"covariates\"))\n        if(cc != \"\") stop(cc)\n      }\n\n      ## OK. append variables.\n      glmdata <- data.frame(glmdata, V)   \n\n      ## check IsOffset matches Vnames\n      if(length(IsOffset) != length(Vnames)) {\n        if(length(IsOffset) == 1)\n          IsOffset <- rep.int(IsOffset, length(Vnames))\n        else\n          stop(\"Internal error: IsOffset has wrong length\", call.=FALSE)\n      }\n  \n      ## Keep only those quadrature points for which the\n      ## conditional intensity is nonzero. \n\n      ##KEEP  <- apply(V != -Inf, 1, all)\n      .mpl$KEEP  <- matrowall(V != -Inf)\n\n      .mpl$SUBSET <- .mpl$SUBSET & .mpl$KEEP\n\n      ## Check that there are at least some data and dummy points remaining\n      datremain <- .mpl$Z[.mpl$SUBSET]\n      somedat <- any(datremain)\n      somedum <- !all(datremain)\n      if(warn.unidentifiable && !(somedat && somedum)) {\n        ## Model would be unidentifiable if it were fitted.\n        ## Register problem\n        is.identifiable <- FALSE\n        if(ndata == 0) {\n          complaint <- \"model is unidentifiable: data pattern is empty\"\n        } else {\n          offending <- !c(somedat, somedum)\n          offending <- c(\"all data points\", \"all dummy points\")[offending]\n          offending <- paste(offending, collapse=\" and \")\n          complaint <- paste(\"model is unidentifiable:\",\n                             offending, \"have zero conditional intensity\")\n        }\n        details <- list(data=!somedat,\n                        dummy=!somedum,\n                        print=complaint)\n        problems <- append(problems, list(unidentifiable=details))\n      }\n\n      ## check whether the model has zero likelihood:\n      ## check whether ANY data points have zero conditional intensity\n      if(any(.mpl$Z & !.mpl$KEEP)) {\n        howmany <- sum(.mpl$Z & !.mpl$KEEP)\n        complaint <- paste(howmany,\n                           \"data point(s) are illegal\",\n                           \"(zero conditional intensity under the model)\")\n        details <- list(illegal=howmany,\n                        print=complaint)\n        problems <- append(problems, list(zerolikelihood=details))\n        if(warn.illegal && is.identifiable)\n          warning(paste(complaint,\n                        \". Occurred while executing: \",\n                        callstring, sep=\"\"),\n                  call. = FALSE)\n        likelihood.is.zero <- TRUE\n      }\n    }\n  \n    ##################     S u b s e t   ###################\n\n    if(correction == \"border\") \n      .mpl$SUBSET <- .mpl$SUBSET & .mpl$DOMAIN\n  \n    if(!is.null(subsetexpr)) {\n      ## user-defined subset expression\n      USER.SUBSET <- eval(subsetexpr, glmdata, environment(trend))\n      if(is.owin(USER.SUBSET)) {\n        USER.SUBSET <- inside.owin(P$x, P$y, USER.SUBSET)\n      } else if(is.im(USER.SUBSET)) {\n        USER.SUBSET <- as.logical(USER.SUBSET[P, drop=FALSE])\n        if(anyNA(USER.SUBSET)) \n          USER.SUBSET[is.na(USER.SUBSET)] <- FALSE\n      }\n      if(!(is.logical(USER.SUBSET) || is.numeric(USER.SUBSET)))\n        stop(\"Argument 'subset' should yield logical values\", call.=FALSE)\n      if(anyNA(USER.SUBSET)) {\n        USER.SUBSET[is.na(USER.SUBSET)] <- FALSE\n        warning(\"NA values in argument 'subset' were changed to FALSE\",\n                call.=FALSE)\n      }\n      .mpl$SUBSET <- .mpl$SUBSET & USER.SUBSET\n    }\n                        \n    glmdata <- cbind(glmdata,\n                     data.frame(.mpl.SUBSET=.mpl$SUBSET,\n                                stringsAsFactors=FALSE))\n\n    #################  F o r m u l a   ##################################\n\n    if(!want.trend) trend <- ~1 \n    trendpart <- paste(as.character(trend), collapse=\" \")\n    if(!want.inter)\n      rhs <- trendpart\n    else {\n      VN <- Vnames\n      ## enclose offset potentials in 'offset(.)'\n      if(any(IsOffset))\n        VN[IsOffset] <- paste(\"offset(\", VN[IsOffset], \")\", sep=\"\")\n      rhs <- paste(c(trendpart, VN), collapse= \"+\")\n    }\n    fmla <- paste(\".mpl.Y \", rhs)\n    fmla <- as.formula(fmla)\n\n    ## experimental - attempt to include functions in scope\n    environment(fmla) <- environment(trend)\n    \n    ##  character string of trend formula (without Vnames)\n    trendfmla <- paste(\".mpl.Y \", trendpart)\n\n    ####\n    result <- list(fmla=fmla, trendfmla=trendfmla,\n                   covariates=if(updatecovariates) covariates else NULL,\n                   glmdata=glmdata, Vnames=Vnames, IsOffset=IsOffset,\n                   subsetexpr=subsetexpr,\n                   problems=problems,\n                   likelihood.is.zero=likelihood.is.zero,\n                   is.identifiable=is.identifiable,\n                   computed=computed,\n                   vnamebase=vnamebase, vnameprefix=vnameprefix,\n                   forbid=forbid, Xweights=Xweights)\n    return(result)\n  }\n\n  check.clashes <- function(forbidden, offered, where) {\n    name.match <- outer(forbidden, offered, \"==\")\n    if(any(name.match)) {\n      is.matched <- apply(name.match, 2, any)\n      matched.names <- (offered)[is.matched]\n      if(sum(is.matched) == 1) {\n        return(paste(\"The variable\",sQuote(matched.names),\n                   \"in\", where, \"is a reserved name\"))\n      } else {\n        return(paste(\"The variables\",\n                   paste(sQuote(matched.names), collapse=\", \"),\n                   \"in\", where, \"are reserved names\"))\n      }\n    }\n    return(\"\")\n  }\n\n  mpl.prepare\n})"

const rtdal007846Source0004 = `mpl.get.covariates <- local({

  mpl.get.covariates <- function(covariates, locations, type="locations",
                                 covfunargs=list(),
                                 need.deriv=FALSE) {
    covargname <- sQuote(short.deparse(substitute(covariates)))
    locargname <- sQuote(short.deparse(substitute(locations)))
    if(is.null(covfunargs)) covfunargs <- list()
    ## extract spatial coordinates
    x <- locations$x
    y <- locations$y
    if(is.null(x) || is.null(y)) {
      xy <- xy.coords(locations)
      x <- xy$x
      y <- xy$y
    }
    if(is.null(x) || is.null(y))
      stop(paste("Can't interpret", locargname, "as x,y coordinates"))
    ## extract marks if any
    m <- locations$marks 
    markinfo <- if(is.null(m)) NULL else list(marks=m)
    ## validate covariates and extract values
    n <- length(x)
    if(is.data.frame(covariates)) {
      if(nrow(covariates) != n)
        stop(paste("Number of rows in", covargname, 
                   "does not equal the number of", type))
      return(covariates)
    } else if(is.list(covariates)) {
      if(length(covariates) == 0)
        return(as.data.frame(matrix(, n, 0)))
      if(any(islin <- unlist(lapply(covariates, inherits, what="lintess")))) {
        ## convert 'lintess' objects to 'linfun' for handling
        if(requireNamespace("spatstat.linnet", quietly=TRUE) &&
           isNamespaceLoaded("spatstat.linnet")) {
          covariates[islin] <- lapply(covariates[islin],
                                      spatstat.linnet::as.linfun)
        } else {
          stop(paste("The package", sQuote("spatstat.linnet"),
                     "is required to handle", sQuote("lintess"),
                     "objects"))
        }
      }
      ## recognise type of each covariate
      isim   <- unlist(lapply(covariates, is.im))
      isfun  <- unlist(lapply(covariates, is.function))
      iswin  <- unlist(lapply(covariates, is.owin))
      istess <- unlist(lapply(covariates, is.tess))
      isnum  <- unlist(lapply(covariates, is.number))
      if(!all(isim | isfun | isnum | iswin | istess))
        stop(paste("Each entry in the list", covargname, 
                   "should be an image, a function,",
                   "a window, a tessellation or a single number"))
      if(sum(nzchar(names(covariates))) < length(covariates))
        stop(paste("Some entries in the list",
                   covargname, "are un-named"))
      ## look up values of each covariate at the quadrature points
      values <- unclass(covariates)
      values[isim] <- lapply(covariates[isim], lookup.im, x=x, y=y,
                             naok=TRUE, strict=FALSE)
      values[isfun] <- vf <- lapply(covariates[isfun], evalfxy, x=x, y=y,
                                    extra=append(covfunargs, markinfo))
      values[isnum] <- lapply(covariates[isnum], rep, length(x))
      values[iswin] <- lapply(covariates[iswin], insidexy, x=x, y=y)
      values[istess] <- lapply(covariates[istess], tileindex, x=x, y=y)
      result <- as.data.frame(values)
      if(need.deriv && any(isfun)) {
        ## check for gradient/hessian attributes of function values
        grad <- lapply(vf, attr, which="gradient")
        hess <- lapply(vf, attr, which="hessian")
        grad <- grad[!unlist(lapply(grad, is.null))]
        hess <- hess[!unlist(lapply(hess, is.null))]
        if(length(grad) > 0 || length(hess) > 0)
          attr(result, "derivatives") <- list(gradient=grad, hessian=hess)
      }
      return(result)
    } 
    stop(paste(covargname, "must be either a data frame or a list"))
  }

  ## functions for 'apply'
  evalfxy <- function(f, x, y, extra) {
    if(length(extra) == 0)
      return(f(x,y))
    ## extra arguments must be matched explicitly by name
    ok <- names(extra) %in% names(formals(f))
    z <- do.call(f, append(list(x,y), extra[ok]))
    return(z)
  }

  insidexy <- function(w, x, y) { inside.owin(x, y, w) }

  is.number <- function(x) { is.numeric(x) && (length(x) == 1) }

  mpl.get.covariates
})`

const rtdal007846Source0005 = `bt.frame <- function(Q, trend=~1, interaction=NULL,
                      ...,
                      covariates=NULL,
                      correction="border", rbord=0,
                      use.gam=FALSE, allcovar=FALSE) {
  prep <- mpl.engine(Q, trend=trend, interaction=interaction,
                     ..., covariates=covariates,
                     correction=correction, rbord=rbord,
                     use.gam=use.gam, allcovar=allcovar,
                     preponly=TRUE, forcefit=TRUE)
  class(prep) <- unique(c("bt.frame", class(prep)))
  return(prep)
}`

const rtdal007846Source0006 = `print.bt.frame <- function(x, ...) {
  cat("Model frame for Berman-Turner device\n")
  df <- x$glmdata
  cat(paste("$glmdata: Data frame with", nrow(df), "rows and",
            ncol(df), "columns\n"))
  cat("          Column names:\t")
  cat(paste(paste(names(df),collapse="\t"), "\n"))
  cat("Complete model formula ($fmla):\t")
  print(x$fmla)
  info <- x$info
  if(info$want.trend) {
    cat("Trend:\tyes\nTrend formula string ($trendfmla):\t")
    cat(paste(x$trendfmla, "\n"))
  } else cat("Trend:\tno\n")
  cat("Interaction ($info$interaction):\t")
  inte <- info$interaction
  if(is.null(inte))
    inte <- Poisson()
  print(inte, family=FALSE, brief=TRUE)
  if(!is.poisson.interact(inte)) {
    cat("Internal names of interaction variables ($Vnames):\t")
    cat(paste(x$Vnames, collapse="\t"))
    cat("\n")
  }
  edge <- info$correction
  cat(paste("Edge correction ($info$correction):\t", sQuote(edge), "\n"))
  if(edge == "border") 
    cat(paste("\tBorder width ($info$rbord):\t", info$rbord, "\n"))
  if(length(x$problems) > 0) {
    cat("Problems:\n")
    print(x$problems)
  }
  if(length(x$computed) > 0)
    cat(paste("Frame contains saved computations for",
              commasep(dQuote(names(x$computed)))))
  return(invisible(NULL))
}`

const rtdal007846Source0007 = `partialModelMatrix <- function(X, D, model, callstring="", ...) {
  ## X = 'data'
  ## D = 'dummy'
  Q <- quad(X,D)
  P <- union.quad(Q)
  trend <- model$trend
  inter <- model$interaction
  covar <- model$covariates
  prep  <- mpl.prepare(Q, X, P, trend, inter, covar,
                       correction=model$correction,
                       rbord=model$rbord,
                       Pname="data points", callstring=callstring,
                       warn.unidentifiable=FALSE,
                       ...)
  fmla    <- prep$fmla
  glmdata <- prep$glmdata
  mof <- model.frame(fmla, glmdata)
  mom <- model.matrix(fmla, mof)

  modelnames <- names(coef(model))
  modelnames <- sub("log(lambda)", "(Intercept)", modelnames, fixed=TRUE)
  if(!isTRUE(all.equal(colnames(mom), modelnames)))
    warning(paste("Internal error: mismatch between",
                  "column names of model matrix",
                  "and names of coefficient vector in fitted model"))

  attr(mom, "mplsubset") <- glmdata$.mpl.SUBSET
  attr(mom, "-Inf") <- prep$forbid
  return(mom)
}`

const rtdal007846Source0008 = `oversize.quad <- function(Q, ..., nU, nX, p=1) {
  ## Determine whether the quadrature scheme is
  ## too large to handle in one piece (in mpl)
  ## for a generic interaction
  ##    nU = number of quadrature points
  ##    nX = number of data points
  ##    p = dimension of statistic 
  if(missing(nU))
    nU <- n.quad(Q)
  if(missing(nX))
    nX <- npoints(Q$data)
  nmat <- as.double(nU) * nX
  nMAX <- spatstat.options("maxmatrix")/p
  needsplit <- (nmat > nMAX)
  return(needsplit)
}`

const rtdal007846Source0010 = `evalInteraction <- function(X, P, E = equalpairs(P, X), 
                            interaction, correction,
                            splitInf=FALSE,
                            ...,
                            precomputed=NULL,
                            savecomputed=FALSE) {

  ## evaluate the interaction potential
  ## (does not assign/touch the variable names)

  verifyclass(interaction, "interact")

  ## handle Poisson case
  if(is.poisson(interaction)) {
    out <- matrix(numeric(0), nrow=npoints(P), ncol=0)
    attr(out, "IsOffset") <- logical(0)
    if(splitInf)
      attr(out, "-Inf") <- logical(nrow(out))
    return(out)
  }
  
  ## determine whether to use fast evaluation in C
  dofast <- (spatstat.options("fasteval") %in% c("on", "test")) &&
            !is.null(cando <- interaction$can.do.fast) &&
            cando(X, correction, interaction$par) &&
            !is.null(interaction$fasteval)

  ## determine whether to split quadscheme into blocks
  if(dofast) {
    dosplit <- FALSE
  } else {
    ## decide whether the quadrature scheme is too large to handle in one piece
    needsplit <- oversize.quad(nU=npoints(P), nX=npoints(X))

    ## not implemented when savecomputed=TRUE
    dosplit   <- needsplit && !savecomputed
    if(needsplit && savecomputed)
      warning(paste("Oversize quadscheme cannot be split into blocks",
                    "because savecomputed=TRUE;",
                    "memory allocation error may occur"))
  }
  
  if(!dosplit) {
    ## normal case
    V <- evalInterEngine(X=X, P=P, E=E,
                         interaction=interaction,
                         correction=correction,
                         splitInf=splitInf,
                         ...,
                         precomputed=precomputed,
                         savecomputed=savecomputed)
  } else {
    ## Too many quadrature points: split into blocks
    nX <- npoints(X)
    nP <- npoints(P)
    ## Determine which evaluation points are data points
    Pdata <- E[,2]
    ## hence which are dummy points
    Pall <- seq_len(nP)
    Pdummy <- if(length(Pdata) > 0) Pall[-Pdata] else Pall
    nD <- length(Pdummy)
    ## calculate block sizes
    bls <- quadBlockSizes(nX, nD, announce=TRUE)
    nblocks    <- bls$nblocks
    nperblock  <- bls$nperblock
    ##
    seqX <- seq_len(nX)
    EX <- cbind(seqX, seqX)
    ##
    for(iblock in 1:nblocks) {
      first <- min(nD, (iblock - 1) * nperblock + 1)
      last  <- min(nD, iblock * nperblock)
      ## extract dummy points  
      Di <- P[Pdummy[first:last]]
      Pi <- superimpose(X, Di, check=FALSE, W=X$window)
      ## evaluate potential
      Vi <- evalInterEngine(X=X, P=Pi, E=EX, 
                            interaction=interaction,
                            correction=correction,
                            splitInf=splitInf,
                            ...,
                            savecomputed=FALSE)
      Mi <- attr(Vi, "-Inf")
      if(iblock == 1) {
        V <- Vi
        M <- Mi
      } else {
        ## tack on the glm variables for the extra DUMMY points only
        V <- rbind(V, Vi[-seqX, , drop=FALSE])
        if(splitInf && !is.null(M))
          M <- c(M, Mi[-seqX])
      }
    }
    ## The first 'nX' rows of V contain values for X.
    ## The remaining rows of V contain values for dummy points.
    if(length(Pdata) == 0) {
      ## simply discard rows corresponding to data
      V <- V[-seqX, , drop=FALSE]
      if(splitInf && !is.null(M)) 
        M <- M[-seqX]
    } else {
      ## replace data in correct position
      ii <- integer(nP)
      ii[Pdata] <- seqX
      ii[Pdummy] <- (nX+1):nrow(V)
      V <- V[ii, , drop=FALSE]
      if(splitInf && !is.null(M))
        M <- M[ii]
    }
    attr(V, "-Inf") <- M
  }
  return(V)
}`

const rtdal007846Source0011 = `evalInterEngine <- function(X, P, E, 
                            interaction, correction,
                            splitInf=FALSE, 
                            ...,
                            Reach = NULL,
                            precomputed=NULL,
                            savecomputed=FALSE) {

  ## fast evaluator (C code) may exist
  fasteval <- interaction$fasteval
  cando    <- interaction$can.do.fast
  par      <- interaction$par
  feopt    <- spatstat.options("fasteval")
  dofast   <- !is.null(fasteval) &&
              (is.null(cando) || cando(X, correction,par)) &&
              (feopt %in% c("on", "test")) &&
              (!splitInf || ("splitInf" %in% names(formals(fasteval))))
    
  V <- NULL
  if(dofast) {
    if(feopt == "test")
      message("Calling fasteval")
    V <- fasteval(X, P, E,
                  interaction$pot, interaction$par, correction,
                  splitInf=splitInf, ...)
  }
  if(is.null(V)) {
    ## use generic evaluator for family
    evaluate <- interaction$family$eval
    evalargs <- names(formals(evaluate))

    if(splitInf && !("splitInf" %in% evalargs))
      stop("Sorry, the", interaction$family$name, "interaction family",
           "does not support calculation of the positive part",
           call.=FALSE)

    if(is.null(Reach)) Reach <- reach(interaction)

    if("precomputed" %in% evalargs) {
      ## Use precomputed data
      ## version 1.9-3 onward (pairwise and pairsat families)
      V <- evaluate(X, P, E,
                    interaction$pot,
                    interaction$par,
                    correction=correction,
                    splitInf=splitInf,
                    ...,
                    Reach=Reach, 
                    precomputed=precomputed,
                    savecomputed=savecomputed)
    } else {
      ## Cannot use precomputed data
      ## Object created by earlier version of ppm
      ## or not pairwise/pairsat interaction
      V <- evaluate(X, P, E,
                    interaction$pot,
                    interaction$par,
                    correction=correction,
                    splitInf=splitInf,
                    ..., Reach=Reach)
    }
  }

  return(V)
}`

const rtdal007846Source0012 = `deltasuffstat <- local({
  
  deltasuffstat <- function(model, ...,
                            restrict=c("pairs", "first", "none"),
			    dataonly=TRUE,
                            sparseOK=TRUE,
                            quadsub=NULL,
                            force=FALSE,
                            warn.forced=FALSE,
                            verbose=warn.forced,
                            use.special=TRUE) {
    stopifnot(is.ppm(model))
    sparseOK <- !isFALSE(sparseOK)  # NULL -> TRUE
    restrict <- match.arg(restrict)
    
    if(dataonly) {
      X <- data.ppm(model)
      nX <- npoints(X)
    } else {
      X <- quad.ppm(model)
      if(!is.null(quadsub)) {
        z <- is.data(X)
        z[quadsub] <- FALSE
        if(any(z))
          stop("subset 'quadsub' must include all data points", call.=FALSE)
        X <- X[quadsub]
      }
      nX <- n.quad(X)
    }
    ncoef <- length(coef(model))
    inte <- as.interact(model)

    if(!sparseOK && exceedsMaxArraySize(nX, nX, ncoef)) 
      stop(paste("Array dimensions too large",
                 paren(paste(c(nX, nX, ncoef), collapse=" x ")),
                 "for non-sparse calculation of variance terms"),
           call.=FALSE)

    zeroes <- if(!sparseOK) array(0, dim=c(nX, nX, ncoef)) else
                            sparse3Darray(dims=c(nX, nX, ncoef))
    
    if(is.poisson(inte))
      return(zeroes)
    
    ## Get names of interaction terms in model (including offsets)
    f <- fitin(model)
    Inames <- f$Vnames
    IsOffset <- f$IsOffset
    hasInf <- !identical(inte$hasInf, FALSE)
    
    ## Offset terms do not contribute to sufficient statistic
    if(all(IsOffset) && !hasInf)
      return(zeroes)
    
    ## Nontrivial interaction terms must be computed.
    ## Look for member function $delta2 in the interaction
    v <- NULL
    v.is.full <- FALSE
    if(use.special) {
      ## Use specialised $delta2 for interaction,if available
      if(is.function(delta2 <- inte$delta2)) 
        v <- delta2(X, inte, model$correction, sparseOK=sparseOK)
      ## Use generic $delta2 for the family, if available
      if(is.null(v) && is.function(delta2 <- inte$family$delta2))
        v <- delta2(X, inte, model$correction, sparseOK=sparseOK)
    }
    ## no luck?
    if(is.null(v)) {
      if(!force)
        return(NULL)
      ## use brute force algorithm
      if(warn.forced)
        warning("Reverting to brute force to compute interaction terms",
                call.=FALSE)
      v <- if(dataonly) deltasufX(model, sparseOK, verbose=verbose) else
           deltasufQ(model, quadsub, sparseOK, verbose=verbose)
      v.is.full <- TRUE
    }
    
    ## extract hard core information
    deltaInf <- attr(v, "deltaInf")

    ## ensure 'v' is a 3D array
    if(length(dim(v)) != 3) {
      if(is.matrix(v)) {
        v <- array(v, dim=c(dim(v), 1))
      } else if(inherits(v, "sparseMatrix")) {
        v <- as.sparse3Darray(v)
      }
    }

    if(!sparseOK) {
      if(inherits(v, "sparse3Darray"))
        v <- as.array(v)
      if(inherits(deltaInf, "sparseMatrix"))
        deltaInf <- as.matrix(deltaInf)
    }

    if(restrict != "none") {
      ## kill contributions from points outside the domain of pseudolikelihood
      ## (e.g. points in the border region)
      use <- if(dataonly) getppmdatasubset(model) else
             if(is.null(quadsub)) getglmsubset(model) else
             getglmsubset(model)[quadsub]
      if(any(kill <- !use)) {
        switch(restrict,
 	       pairs = { v[kill,kill,] <- 0 },
	       first = { v[kill,,] <- 0 },
	       none = {})
        if(!is.null(deltaInf)) {
          switch(restrict,
                 pairs = { deltaInf[kill,kill] <- FALSE },
                 first = { deltaInf[kill,] <- FALSE },
                 none = {})
        }
      }
    }

    ## Make output array, with planes corresponding to model coefficients
    if(v.is.full) {
      ## Planes of 'v' already correspond to coefficients of model
      cnames <- names(coef(model))
      ## Remove any offset interaction terms
      ## (e.g. Hardcore interaction): these do not contribute to suff stat
      if(any(IsOffset)) {
        retain <- is.na(match(cnames, Inames[IsOffset]))
        v <- v[ , , retain, drop=FALSE]
        Inames <- Inames[!IsOffset]
      }
      result <- v
    } else {
      ## Planes of 'v' correspond to interaction terms only.
      ## Fill out the first order terms with zeroes
      result <- zeroes
      if(length(Inames) != dim(v)[3])
        stop(paste("Internal error: deltasuffstat:",
                   "number of planes of v =", dim(v)[3],
                   "!= number of interaction terms =", length(Inames)),
             call.=FALSE)
      ## Offset terms do not contribute to sufficient statistic
      if(any(IsOffset)) {
        v <- v[ , , !IsOffset, drop=FALSE]
        Inames <- Inames[!IsOffset]
      }
      ## Map planes of 'v' into coefficients
      Imap <- match(Inames, names(coef(model)))
      if(anyNA(Imap))
        stop(paste("Internal error: deltasuffstat:",
                   "cannot match interaction coefficients"))
      if(length(Imap) > 0) {
        ## insert 'v' into array
        result[ , , Imap] <- v
      }
    }
    ## pack up
    attr(result, "deltaInf") <- deltaInf
    return(result)
  }

  ## compute deltasuffstat using partialModelMatrix

  deltasufX <- function(model, sparseOK=TRUE, verbose=FALSE) {
    stopifnot(is.ppm(model))
    X <- data.ppm(model)
    hasInf <- !identical(model$interaction$hasInf, FALSE)
  
    nX <- npoints(X)
    p <- length(coef(model))

    m <- model.matrix(model, splitInf=hasInf)
    if(hasInf) {
      isInf <- attr(m, "-Inf")
      hasInf <- !is.null(isInf)
    }

    isdata <- is.data(quad.ppm(model))
    m <- m[isdata, ,drop=FALSE]
    if(hasInf)
      isInf <- isInf[isdata]
    ok <- getppmdatasubset(model)
    
    ## canonical statistic before and after deleting X[j]
    ## mbefore[ , i, j] = h(X[i] | X)
    ## mafter[ , i, j] = h(X[i] | X[-j])
    ## where h(u|x) is the canonical statistic of the *positive* cif
    dimwork <- c(p, nX, nX)
    if(!sparseOK) {
      mafter <- mbefore <- array(t(m), dim=dimwork)
      isInfafter <- isInfbefore <-
        if(!hasInf) NULL else matrix(isInf, dim=dimwork[-1]) 
    } else {
      ## make empty arrays; fill in values later
      ## (but only where they might change)
      mafter <- mbefore <- sparse3Darray(dims=dimwork)
      isInfafter <- isInfbefore <- if(!hasInf) NULL else
        sparseMatrix(i=integer(0), j=integer(0), x=logical(0),
                     dims=dimwork[-1])
    }

    ## identify close pairs
    R <- reach(model)
    if(is.finite(R)) {
      cl <- closepairs(X, R, what="indices")
      I <- cl$i
      J <- cl$j
      cl2 <- closepairs(X, 2*R, what="indices")
      I2 <- cl2$i
      J2 <- cl2$j
    } else {
      ## either infinite reach, or something wrong
      IJ <- expand.grid(I=1:nX, J=1:nX)
      IJ <- subset(IJ, I != J)
      I2 <- I <- IJ$I
      J2 <- J <- IJ$J
    }
    ## DO NOT RESTRICT - THIS IS NOW DONE IN deltasuffstat
    ## filter:  I and J must both belong to the nominated subset 
    ## okIJ <- ok[I] & ok[J]
    ## I <- I[okIJ]
    ## J <- J[okIJ]
    ##
    if(length(I) > 0 && length(J) > 0) {
      ## .............. loop over pairs ........................
      uniqueI <- unique(I)
      npairs <- length(uniqueI)
      pstate <- list()
      if(verbose) 
        splat("Examining", npairs, "pairs of data points...")
      ## The following ensures that 'empty' and 'X' have compatible marks 
      empty <- X[integer(0)]
      ## 
      ## Run through pairs
      for(iter in seq_len(npairs)) {
        i <- uniqueI[iter]
        ## all points within 2R
        J2i <- unique(J2[I2==i])
        ## all points within R
        Ji  <- unique(J[I==i])
        nJi <- length(Ji)
        if(nJi > 0) {
          Xi <- X[i]
          ## neighbours of X[i]
          XJi <- X[Ji]
          ## replace X[-i] by X[-i] \cap b(0, 2R)
          X.i <- X[J2i]
          nX.i <- length(J2i)
          ## index of XJi in X.i
          J.i <- match(Ji, J2i)
          if(anyNA(J.i))
            stop("Internal error: Ji not a subset of J2i")
          ## values of sufficient statistic 
          ##    h(X[j] | X[-i]) = h(X[j] | X[-c(i,j)]
          ## for all j
          pmj <- snipModelMatrix(X.i, empty, model, J.i, hasInf)
          if(hasInf) zzj <- attr(pmj, "-Inf")
          ## sufficient statistic in reverse order
          ##    h(X[i] | X[-j]) = h(X[i] | X[-c(i,j)]
          ## for all j
          pmi <- matrix(, nJi, p)
          zzi <- logical(nJi)
          for(k in 1:nJi) {
            ## j <- Ji[k]
            ## X.ij <- X[-c(i,j)]
            X.ij <- X.i[-J.i[k]]
            pmik <- snipModelMatrix(X.ij, Xi, model, nX.i, hasInf)
            pmi[k, ] <- pmik
            if(hasInf) zzi[k] <- attr(pmik, "-Inf")
          }
          ##
          if(!sparseOK) {
            mafter[ , Ji, i] <- t(pmj)
            mafter[ , i, Ji] <- t(pmi)
            if(hasInf) {
              isInfafter[Ji, i] <- zzj
              isInfafter[i, Ji] <- zzi
            }
          } else {
            mafter[ , Ji, i] <- array(t(pmj), dim=c(p, nJi, 1))
            mafter[ , i, Ji] <- array(t(pmi), dim=c(p, 1, nJi))
            mbefore[ , Ji, i] <- array(t(m[Ji,]), dim=c(p, nJi, 1))
            mbefore[ , i, Ji] <- array(m[i,], dim=c(p, 1, nJi))
            if(hasInf) {
              isInfafter[Ji, i] <- zzj
              isInfafter[i, Ji] <- zzi
              isInfbefore[Ji, i] <- isInf[Ji]
              isInfbefore[i, Ji] <- isInf[i]
            }
          } 
        }
        if(verbose)
          pstate <- progressreport(iter, npairs, state=pstate)
      }
    }
        
    ##  delta[ ,i,j] = h(X[i] | X) - h(X[i] | X[-j])
    delta <- mbefore - mafter
    ## delta[i, j, ] = h(X[i] | X) - h(X[i] | X[-j])
    delta <- aperm(delta, c(2,3,1))
    ##
    if(hasInf) {
      deltaInf <- isInfbefore - isInfafter
      attr(delta, "deltaInf") <- deltaInf
    }
    return(delta)
  }

  deltasufQ <- function(model, quadsub, sparseOK, verbose=FALSE) {
    stopifnot(is.ppm(model))
    hasInf <- !identical(model$interaction$hasInf, FALSE)

    p <- length(coef(model))
    
    Q <- quad.ppm(model)
    ok <- getglmsubset(model)

    m <- model.matrix(model, splitInf=hasInf)
    if(hasInf) {
      isInf <- attr(m, "-Inf")
      hasInf <- !is.null(isInf)
    }

    if(!is.null(quadsub)) {
      Q <- Q[quadsub]
      m <- m[quadsub, , drop=FALSE]
      ok <- ok[quadsub]
      if(hasInf) isInf <- isInf[quadsub]
    }
    
    X <- Q$data
    U <- union.quad(Q)
    nU <- npoints(U)
    nX <- npoints(X)
    isdata <- is.data(Q)
    isdummy <- !isdata
    
    ## canonical statistic before and after adding/deleting U[j]
    dimwork <- c(p, nU, nU)
    if(!sparseOK) {
      mafter <- mbefore <- array(t(m), dim=dimwork)
      delta <- array(0, dim=dimwork)
      isInfafter <- isInfbefore <- deltaInf <-
        if(!hasInf) NULL else matrix(isInf, dim=dimwork[-1])
    } else {
      ## make empty arrays; fill in values later
      ## [but only where they might change]
      mafter <- mbefore <- delta <- sparse3Darray(dims=dimwork)
      isInfafter <- isInfbefore <- deltaInf <-
        if(!hasInf) NULL else sparseMatrix(i=integer(0), j=integer(0),
                                           x=logical(0),
                                           dims=dimwork[-1])
    }
    ##   mbefore[ , i, j] = h(U[i] | X)
    ## For data points X[j]
    ##   mafter[ , i, j] = h(U[i] | X[-j])
    ##   delta[ , i, j] = h(U[i] | X) - h(U[i] | X[-j])
    ## For dummy points X[j]
    ##   mafter[ , i, j] = h(U[i] | X \cup U[j])
    ##   delta[ , i, j] = h(U[i] | X \cup U[j]) - h(U[i] | X)

    changesign <- ifelseAB(isdata, -1, 1)
  
    ## identify close pairs of quadrature points
    R <- reach(model)
    if(is.finite(R)) {
      cl <- closepairs(U, R, what="indices")
      I <- cl$i
      J <- cl$j
      cl2 <- closepairs(U, 2*R, what="indices")
      I2 <- cl2$i
      J2 <- cl2$j
    } else {
      ## either infinite reach, or something wrong
      IJ <- expand.grid(I=1:nU, J=1:nX)
      IJ <- IJ[ with(IJ, I != J), ]
      I2 <- I <- IJ$I
      J2 <- J <- IJ$J
    }

    ## filter:  I and J must both belong to the nominated subset 
    okIJ <- ok[I] & ok[J]
    I <- I[okIJ]
    J <- J[okIJ]
    ##
    if(length(I) > 0 && length(J) > 0) {
      ## .............. loop over pairs of quadrature points ...............
      ## Run through pairs
      uI <- unique(I)
      zI <- isdata[uI]
      uIdata <- uI[zI]
      uIdummy <- uI[!zI]
      nuIdata <- length(uIdata)
      nuIdummy <- length(uIdummy)
      if(verbose) 
        splat("Examining", nuIdata, "+", nuIdummy, "=", nuIdata + nuIdummy,
              "pairs of points")
      ## Run through pairs i, j where 'i' is a data point
      pstate <- list()
      for(iter in seq_len(nuIdata)) {
        i <- uIdata[iter]
        ## all DATA points within 2R of X[i]
        ## This represents X[-i] 
        J2i <- unique(J2[I2==i])
        J2i <- J2i[isdata[J2i]]
        ## all QUADRATURE points within R of X[i]
        Ji  <- unique(J[I==i])
        nJi <- length(Ji)
        if(nJi > 0) {
          isd <- isdata[Ji]
          ## data points which are neighbours of X[i]
          XJi <- X[Ji[isd]]
          ## dummy points which are neighbours of X[i]
          DJi <- U[Ji[!isd]]
          ## replace X[-i] by X[-i] \cap b(0, 2R)
          X.i <- X[J2i]
          nX.i <- length(J2i)
          ## index of XJi in X.i 
          J.i <- match(Ji[isd], J2i)
          if(anyNA(J.i))
            stop("Internal error: Ji[isd] not a subset of J2i")
          ## index of DJi in superimpose(X.i, DJi)
          JDi <- nX.i + seq_len(sum(!isd))
          ## values of sufficient statistic 
          ##    h(X[j] | X[-i]) = h(X[j] | X[-c(i,j)]
          ## for all j
          pmj <- snipModelMatrix(X.i, DJi, model, c(J.i, JDi), hasInf)
          ##
          mafter[ , Ji, i] <- t(pmj)
          if(hasInf)
            isInfafter[Ji, i] <- attr(pmj, "-Inf")
          if(sparseOK) {
            mbefore[ , Ji, i] <- array(t(m[Ji,]), dim=c(p, nJi, 1))
            if(hasInf) isInfbefore[Ji, i] <- isInf[Ji]
          }
        }
        if(verbose)
          pstate <- progressreport(iter, nuIdata, state=pstate)
      }
      ## Run through pairs i, j where 'i' is a dummy point
      pstate <- list()
      for(iter in seq_len(nuIdummy)) {
        i <- uIdummy[iter]
        ## all DATA points within 2R of U[i]
        J2i <- unique(J2[I2==i])
        J2i <- J2i[isdata[J2i]]
        ## all QUADRATURE points within R of U[i]
        Ji  <- unique(J[I==i])
        nJi <- length(Ji)
        if(nJi > 0) {
          isd <- isdata[Ji]
          JiData <- Ji[isd]
          JiDummy <- Ji[!isd]
          ## data points which are neighbours of U[i]
          XJi <- X[JiData]
          ## dummy points which are neighbours of U[i]
          DJi <- U[JiDummy]
          ## replace X \cup U[i] by (X \cap b(0, 2R)) \cup U[i]
          J2Ui <- c(J2i, i)
          XUi <- U[J2Ui]
          nXUi <- length(J2Ui)
          ## index of XJi in X.i 
          J.i <- match(JiData, J2Ui)
          if(anyNA(J.i))
            stop("Internal error: Ji[isd] not a subset of J2i")
          ## index of DJi in superimpose(X.i, DJi)
          JDi <- nXUi + seq_len(length(JiDummy))
          ## values of sufficient statistic 
          ##    h(X[j] | X \cup U[i]) 
          ## for all j
          pmj <- snipModelMatrix(XUi, DJi, model, c(J.i, JDi), hasInf)
          ##
          JiSort <- c(JiData, JiDummy)
          if(!sparseOK) {
            mafter[ , JiSort, i] <- t(pmj)
            if(hasInf)
              isInfafter[JiSort, i] <- attr(pmj, "-Inf")
          } else {
            mafter[ , JiSort, i]  <- array(t(pmj), dim=c(p, nJi, 1))
            mbefore[ , JiSort, i] <- array(t(m[JiSort,]), dim=c(p, nJi, 1))
            if(hasInf) {
              isInfafter[JiSort, i] <- attr(pmj, "-Inf")
              isInfbefore[JiSort, i] <- isInf[JiSort]
            }
          }
        }
        if(verbose)
          pstate <- progressreport(iter, nuIdummy, state=pstate)
      }
    }
        
    ##  delta[ ,i,j] = h(X[i] | X) - h(X[i] | X[-j])
    delta[ , , isdata] <- mbefore[, , isdata] - mafter[ , , isdata]
    ##  delta[ ,i,j] = h(X[i] | X \cup U[j]) - h(X[i] | X)
    delta[ , , isdummy] <- mafter[, , isdummy] - mbefore[ , , isdummy]
    ## rearrange: new delta[i,j,] = old delta[, i, j]
    delta <- aperm(delta, c(2,3,1))
    ##
    if(hasInf) {
      deltaInf[ , isdata]  <- isInfbefore[ , isdata] - isInfafter[ , isdata]
      deltaInf[ , isdummy] <- isInfafter[ , isdummy] - isInfbefore[ , isdummy]
      attr(delta, "deltaInf") <- deltaInf
    }
    return(delta)
  }

  snipModelMatrix <- function(X, D, model, retain, splitInf=FALSE) {
    M <- partialModelMatrix(X, D, model, splitInf=splitInf)
    if(splitInf) isInf <- attr(M, "-Inf")
    M <- M[retain, , drop=FALSE]
    if(splitInf) attr(M, "-Inf") <- isInf[retain]
    return(M)
  }
      
  deltasuffstat
})`

