			runtime.SetLocal(env, "result", runtime.MustCallIn(ctx, env, "-", runtime.PrimitiveArg(runtime.NumericVector(1)), runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "[", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "P")), runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "W")), runtime.NamedPrimitiveArg("drop", runtime.LogicalScalar(false)), runtime.NamedPrimitiveArg("tight", runtime.LogicalScalar(true))))))
