const rtdal007891Source0002 = `response.glm <- response.lm <- function(object) {
  mo <- object$model
  if(is.null(mo)) return(NULL)
  te <- terms(object)
  rn <- attr(te, "response")
  if(is.null(rn)) return(NULL)
  y <- mo[,rn]
  return(y)
}`

