const rtdal007895Source0001 = `.Spatstat.Rmhinfo <-
list(
     "Multitype Hardcore process" =
     function(coeffs, inte) {
       # hard core radii r[i,j]
       hradii <- inte$par[["hradii"]]
       return(list(cif='multihard',
                   par=list(hradii=hradii),
                   ntypes=ncol(hradii)))
     },
     "Lennard-Jones process" =
     function(coeffs, inte) {
       pa <- inte$interpret(coeffs,inte)$param
       sigma   <- pa[["sigma"]]
       epsilon <- pa[["epsilon"]]
       return(list(cif='lennard',
                   par=list(sigma=sigma, epsilon=epsilon),
                   ntypes=1))
     },
     "Fiksel process" =
     function(coeffs, inte) {
       hc <- inte$par[["hc"]]
       r  <- inte$par[["r"]]
       kappa <- inte$par[["kappa"]]
       a <- inte$interpret(coeffs,inte)$param$a
       return(list(cif='fiksel',
                   par=list(r=r,hc=hc,kappa=kappa,a=a),
                   ntypes=1))
     },
     "Diggle-Gates-Stibbard process" =
     function(coeffs, inte) {
       rho   <- inte$par[["rho"]]
       return(list(cif='dgs',
                   par=list(rho=rho),
                   ntypes=1))
     },
     "Diggle-Gratton process" =
     function(coeffs, inte) {
       kappa <- inte$interpret(coeffs,inte)$param$kappa
       delta <- inte$par[["delta"]]
       rho   <- inte$par[["rho"]]
       return(list(cif='diggra',
                   par=list(kappa=kappa,delta=delta,rho=rho),
                   ntypes=1))
     },
     "Hard core process" =
     function(coeffs, inte) {
       hc <- inte$par[["hc"]]
       return(list(cif='hardcore',
                   par=list(hc=hc),
                   ntypes=1))
     },
     "Geyer saturation process" =
     function(coeffs, inte) {
       gamma <- inte$interpret(coeffs,inte)$param$gamma
       r <- inte$par[["r"]]
       sat <- inte$par[["sat"]]
       return(list(cif='geyer',
                   par=list(gamma=gamma,r=r,sat=sat),
                   ntypes=1))
     },
     "Soft core process" =
     function(coeffs, inte) {
       kappa <- inte$par[["kappa"]]
       sigma <- inte$interpret(coeffs,inte)$param$sigma
       return(list(cif="sftcr",
                   par=list(sigma=sigma,kappa=kappa),
                   ntypes=1))
     },
     "Strauss process" =
     function(coeffs, inte) {
       gamma <- inte$interpret(coeffs,inte)$param$gamma
       r <- inte$par[["r"]]
       return(list(cif = "strauss",
                   par = list(gamma = gamma, r = r),
                   ntypes=1))
     },
     "Strauss - hard core process" =
     function(coeffs, inte) {
       gamma <- inte$interpret(coeffs,inte)$param$gamma
       r <- inte$par[["r"]]
       hc <- inte$par[["hc"]]
       return(list(cif='straush',
                   par=list(gamma=gamma,r=r,hc=hc),
                   ntypes=1))
     },
     "Triplets process" =
     function(coeffs, inte) {
       gamma <- inte$interpret(coeffs,inte)$param$gamma
       r <- inte$par[["r"]]
       return(list(cif = "triplets",
                   par = list(gamma = gamma, r = r),
                   ntypes=1))
     },
     "Penttinen process" =
     function(coeffs, inte) {
       gamma <- inte$interpret(coeffs,inte)$param$gamma
       r   <- inte$par[["r"]]
       return(list(cif='penttinen',
                   par=list(gamma=gamma, r=r),
                   ntypes=1))
     },
     "Multitype Strauss process" =
     function(coeffs, inte) {
       # interaction radii r[i,j]
       radii <- inte$par[["radii"]]
       # interaction parameters gamma[i,j]
       gamma <- (inte$interpret)(coeffs, inte)$param$gammas
       return(list(cif='straussm',
                   par=list(gamma=gamma,radii=radii),
                   ntypes=ncol(radii)))
     },
     "Multitype Strauss Hardcore process" =
     function(coeffs, inte) {
       # interaction radii r[i,j]
       iradii <- inte$par[["iradii"]]
       # hard core radii r[i,j]
       hradii <- inte$par[["hradii"]]
       # interaction parameters gamma[i,j]
       gamma <- (inte$interpret)(coeffs, inte)$param$gammas
       return(list(cif='straushm',
                   par=list(gamma=gamma,iradii=iradii,hradii=hradii),
                   ntypes=ncol(iradii)))
     },
     "Piecewise constant pairwise interaction process" =
     function(coeffs, inte) {
       r <- inte$par[["r"]]
       gamma <- (inte$interpret)(coeffs, inte)$param$gammas
       h <- stepfun(r, c(gamma, 1))
       return(list(cif='lookup', par=list(h=h),
                   ntypes=1))
     },
     "Area-interaction process" =
     function(coeffs, inte) {
       r <- inte$par[["r"]]
       eta <- (inte$interpret)(coeffs, inte)$param$eta
       return(list(cif='areaint', par=list(eta=eta,r=r), ntypes=1))
     },
     "hybrid Geyer process" =
     function(coeffs, inte) {
       r <- inte$par[["r"]]
       sat <- inte$par[["sat"]]
       gamma <- (inte$interpret)(coeffs,inte)$param$gammas
       return(list(cif='badgey',par=list(gamma=gamma,r=r,sat=sat), ntypes=1))
     },
     "Hybrid interaction"=
     function(coeffs, inte){
       # for hybrids, $par is a list of the component interactions
       interlist <- inte$par
       # check for Poisson components
       ispois <- unlist(lapply(interlist, is.poisson))
       if(all(ispois)) {
         # reduces to Poisson
         Z <- list(cif='poisson', par=list())
         return(Z)
       } else if(any(ispois)) {
         # remove Poisson components
         interlist <- interlist[!ispois]
       }
       # 
       N <- length(interlist)
       cifs <- character(N)
       pars <- vector(mode="list", length=N)
       ntyp <- integer(N)
       for(i in 1:N) {
         interI <- interlist[[i]]
         # forbid hybrids-of-hybrids - these should not occur anyway
         if(interI$name == "Hybrid interaction")
           stop("Simulation of a hybrid-of-hybrid interaction is not implemented")
         # get RMH mapping for I-th component
         siminfoI <- .Spatstat.Rmhinfo[[interI$name]]
         if(is.null(siminfoI))
           stop(paste("Simulation of a fitted", sQuote(interI$name),
                      "has not yet been implemented"),
                call.=FALSE)
         # nameI is the tag that identifies I-th component in hybrid
         nameI  <- names(interlist)[[i]]
         nameI. <- paste(nameI, ".", sep="")
         # find coefficients with prefix that exactly matches nameI.
         Cname  <- names(coeffs)
         prefixlength <- nchar(nameI.)
         Cprefix <- substr(Cname, 1, prefixlength)
         relevant <- (Cprefix == nameI.)
         # extract coefficients
         #   (there may be none, if this interaction is an 'offset')
         coeffsI <- coeffs[relevant]
         # remove the prefix so the coefficients are recognisable to 'siminfoI'
         if(any(relevant)) 
           names(coeffsI) <-
             substr(Cname[relevant], prefixlength+1, max(nchar(Cname)))
         # compute RMH info
         ZI <- siminfoI(coeffsI, interI)
         cifs[i] <- ZI$cif
         pars[[i]] <- ZI$par
         ntyp[i] <- ZI$ntypes
       }
       nt <- unique(ntyp[ntyp != 1])
       if(length(nt) > 1)
         stop(paste("Hybrid components have different numbers of types:",
                    commasep(nt)))
       if(N == 1) {
         # single cif: revert to original format: par is a list of parameters
         Z <- list(cif=cifs[1], par=pars[[1]], ntypes=ntyp)
       } else {
         # hybrid cif: par is a list of lists of parameters
         Z <- list(cif=cifs,    par=pars,      ntypes=ntyp)
       }
       return(Z)
     }
)`

const rtdal007895Source0002 = "rmhmodel.ppm <- function(model, w, ...,\n                         verbose=TRUE, project=TRUE,\n                         control=rmhcontrol(),\n                         new.coef=NULL,\n                         newdata=NULL) {\n  ## converts ppm object `model' into format palatable to rmh.default\n  \n  verifyclass(model, \"ppm\")\n  argh <- list(...)\n\n  if(!is.null(new.coef))\n    model <- tweak.coefs(model, new.coef)\n\n  if(newdata.given <- !is.null(newdata)) {\n    covariates <- newdata\n  } else {\n    covariates <- model$covariates\n  }\n  \n  ## Ensure the fitted model is valid\n  ## (i.e. exists mathematically as a point process)\n  if(!valid.ppm(model)) {\n    if(project) {\n      if(verbose)\n        cat(\"Model is invalid - projecting it\\n\")\n      model <- project.ppm(model, fatal=TRUE)\n    } else stop(\"The fitted model is not a valid point process\")\n  }\n    \n  if(verbose)\n    cat(\"Extracting model information...\")\n    \n  ## Extract essential information\n  Y <- summary(model, quick=\"no variances\")\n\n  if(Y$uses.covars && newdata.given &&\n     !all(ok <- Y$covars.used %in% names(covariates))) {\n    nbad <- sum(!ok)\n    stop(ngettext(nbad, \"Covariate\", \"Covariates\"),\n         commasep(sQuote(Y$covars.used[!ok])),\n         ngettext(nbad, \"is\", \"are\"),\n         \"absent from\", sQuote(\"newdata\"),\n         call.=FALSE)\n  }\n\n  if(Y$marked && !Y$multitype)\n    stop(\"Not implemented for marked point processes other than multitype\")\n\n  if(Y$uses.covars && is.data.frame(covariates)) {\n    stop(paste(\"This model cannot be simulated, because the\",\n               if(newdata.given) {\n                 \"argument 'newdata' is\"\n               } else {\n                 \"covariate values were given as\"\n               },\n               \"a data frame.\"))\n  }\n    \n  ## enforce defaults for `control'\n\n  control <- rmhcontrol(control)\n\n  ## adjust to peculiarities of model\n    \n  control <- rmhResolveControl(control, model)\n    \n  ########  Interpoint interaction\n  if(Y$poisson) {\n    Z <- list(cif=\"poisson\",\n              par=list())  # par is filled in later\n  } else {\n    ## First check version number of ppm object\n    if(Y$antiquated) \n      stop(paste(\"This model was fitted by a very old version\",\n                 \"of the package: spatstat\", Y$version,\n                 \"; simulation is not possible.\",\n                 \"Re-fit the model using your original code\"))\n    else if(Y$old)\n      warning(paste(\"This model was fitted by an old version\",\n                    \"of the package: spatstat\", Y$version,\n                    \". Re-fit the model using update.ppm\",\n                    \"or your original code\"))\n    ## Extract the interpoint interaction object\n    inte <- Y$entries$interaction\n    ## Determine whether the model can be simulated using rmh\n    siminfo <- .Spatstat.Rmhinfo[[inte$name]]\n    if(is.null(siminfo))\n      stop(paste(\"Simulation of a fitted\", sQuote(inte$name),\n                 \"has not yet been implemented\"))\n      \n    ## Get fitted model's canonical coefficients\n    coeffs <- Y$entries$coef\n    if(newstyle.coeff.handling(inte)) {\n      ## extract only the interaction coefficients\n      Vnames <- Y$entries$Vnames\n      IsOffset <- Y$entries$IsOffset\n      coeffs <- coeffs[Vnames[!IsOffset]]\n    }\n    ## Translate the model to the format required by rmh.default\n    Z <- siminfo(coeffs, inte)\n    if(is.null(Z))\n      stop(\"The model cannot be simulated\")\n    else if(is.null(Z$cif))\n      stop(paste(\"Internal error: no cif returned from .Spatstat.Rmhinfo\"))\n  }\n\n  ## Don't forget the types\n  if(Y$multitype && is.null(Z$types))\n    Z$types <- levels(Y$entries$marks)\n       \n  ######## Window for result \n    \n  if(missing(w) || is.null(w)) {\n    ## check for outdated argument name 'win'\n    if(!is.na(m <- match(\"win\", names(argh)))) {\n      warning(\"Argument 'win' to rmhmodel.ppm is deprecated; use 'w'\")\n      w <- argh[[m]]\n      argh <- argh[-m]\n    } else w <- Y$entries$data$window\n  }\n\n  Z$w <- w\n\n  ######## Expanded window for simulation?\n\n  covims <- if(Y$uses.covars) covariates[Y$covars.used] else NULL\n    \n  wsim <- rmhResolveExpansion(w, control, covims, \"covariate\")$wsim\n      \n  ###### Trend or Intensity ############\n\n  if(verbose)\n    cat(\"Evaluating trend...\")\n    \n  if(Y$stationary) {\n    ## first order terms (beta or beta[i]) are carried in Z$par\n    beta <- as.numeric(Y$trend$value)\n    Z$trend <- NULL\n  } else {\n    ## trend terms present\n    ## all first order effects are subsumed in Z$trend\n    beta <- if(!Y$marked) 1 else rep.int(1, length(Z$types))\n    ## predict on window possibly larger than original data window\n    newcovariates <- if(newdata.given) covariates else NULL\n    Z$trend <- \n      if(wsim$type == \"mask\")\n        predict(model, window=wsim, type=\"trend\", locations=wsim,\n                covariates=newcovariates)\n      else \n        predict(model, window=wsim, type=\"trend\",\n                covariates=newcovariates)\n    if(newdata.given) {\n      ## check for substantial fraction of NA's\n      if(!Y$marked) {\n        Atrend <- area(as.owin(Z$trend))\n      } else {\n        Atrend <- mean(sapply(lapply(Z$trend, as.owin), area))\n      }\n      okfrac <- Atrend/area(wsim)\n      if(okfrac < 0.95) {\n        gripe <- paste(\"The model trend is undefined (NA) at\",\n                       percentage(1 - okfrac),\n                       \"of locations in the simulation window\")\n        if(okfrac < 0.5) \n          stop(gripe, call.=FALSE)\n        warning(paste(paste0(gripe, \";\"),\n                      \"simulations will be generated in a sub-window\",\n                      \"covering only\", percentage(okfrac), \"of the area\"),\n                call.=FALSE)\n      }\n    }\n  }\n    \n  Ncif <- length(Z$cif)\n  if(Ncif == 1) {\n    ## single interaction\n    Z$par[[\"beta\"]] <- beta\n  } else {\n    ## hybrid interaction\n    if(all(Z$ntypes == 1)) {\n      ## unmarked model: scalar 'beta' is absorbed in first cif\n      absorb <- 1\n    } else {\n      ## multitype model: vector 'beta' is absorbed in a multitype cif\n      absorb <- min(which(Z$ntypes > 1))\n    }\n    Z$par[[absorb]]$beta <- beta\n    ## other cifs have par$beta = 1 \n    for(i in (1:Ncif)[-absorb])\n      Z$par[[i]]$beta <- rep.int(1, Z$ntypes[i])\n  }\n  if(verbose)\n    cat(\"done.\\n\")\n  Z <- do.call(rmhmodel, append(list(Z), argh))\n  return(Z)\n}"

