const rtdal007896Source0001 = `addROC <- function(object, scope, high=TRUE, ...) {
  addapply(object, scope=scope, action="roc", high=high, ...)
}`

const rtdal007896Source0002 = "addapply <- function(object, \n                     action=c(\"berman.test\", \"cdf.test\", \"rhohat\", \"roc\"),\n                     scope, ..., high=TRUE) {\n  action <- match.arg(action)\n  modelclasses <- c(\"ppm\", \"kppm\", \"dppm\", \"slrm\", \"lppm\")\n  om <- inherits(object, modelclasses)\n  sm <- inherits(scope, modelclasses)\n  if(!(om || sm))\n    stop(paste(\"Either 'object' or 'scope' should be a fitted model of class\",\n               commasep(modelclasses, \"or\")),\n         call.=FALSE)\n  ## determine reference model and variables (refvars, maxvars)\n  if(om) {\n    ## 'object' is a fitted model defining the reference model\n    reference <- object\n    X <- response(reference)\n    refvars <- termsinformula(formula(reference))\n    #' determine maximal variables from 'scope' \n    if(length(scope) == 0) \n      stop(\"Argument `scope` contains no data\") \n    if(sm) {\n      ## 'scope' is a model too\n      maxvars <- attr(terms(scope), \"term.labels\")\n    } else if(inherits(scope, \"formula\")) {\n      maxvars <- termsinformula(update.formula(reference, scope))\n    } else if(is.character(scope)) {\n      maxvars <- scope\n    } else stop(\"Format of argument `scope` is not understood\")\n  } else {\n    ## 'scope' is a fitted model defining the maximal model\n    maxmodel <- scope\n    X <- response(maxmodel)\n    maxvars <- termsinformula(formula(maxmodel))\n    #' determine the reference model from 'object'\n    if(length(object) == 0) \n      stop(\"Argument `object` contains no data\")\n    if(inherits(object, \"formula\")) {\n      reference <- update(maxmodel, object)\n    } else stop(\"Format of argument `object` is not understood\")\n    refvars <- termsinformula(formula(reference))\n  }\n  ## finally determine scope\n  scope <- setdiff(maxvars, refvars)\n  ## handle 'high'\n  if(length(high) == 1) high <- rep(high, length(scope)) else\n  stopifnot(length(high) == length(scope))\n  #'\n  #' pixel resolution arguments only\n  rezargs <- list(...)[c(\"eps\", \"dimyx\", \"xy\", \"rule.eps\")]\n  rezargs <- rezargs[!sapply(rezargs, is.null)]\n  ## go\n  ns <- length(scope)\n  result <- vector(mode=\"list\", length=ns)\n  for(i in seq_len(ns)) {\n    tt <- scope[i]\n    add.i <- as.formula(paste(\". ~ . + \", tt))\n    fit.i <- update(reference, add.i, env=environment(formula(reference)))\n    mim.i <- do.call(model.images,\n                     append(list(object=fit.i),\n                            rezargs))\n    cov.i <- mim.i[[tt]]\n    result[[i]] <-\n      switch(action,\n             roc = {\n               roc(X, cov.i, ..., baseline=reference, high=high[i])\n             },\n             rhohat = {\n               rhohat(reference, cov.i, ..., covname=tt)\n             },\n             berman.test = {\n               berman.test(reference, cov.i, ..., covname=tt)\n             },\n             cdf.test = {\n               cdf.test(reference, cov.i, ..., covname=tt)\n             })\n  }\n  names(result) <- scope\n  return(as.anylist(result))\n}"

const rtdal007896Source0003 = `dropROC <- function(object, scope=NULL, high=TRUE, ...) {
  dropply(object, action="roc", scope=scope, high=high, ...)
}`

const rtdal007896Source0004 = `dropply <- function(object,
                    action=c("berman.test", "cdf.test", "rhohat", "roc"),
                    scope=NULL, ..., high=TRUE) {
  modelclasses <- c("ppm", "kppm", "dppm", "slrm", "lppm")
  if(!inherits(object, modelclasses))
    stop(paste("'object' should be a fitted model of class",
               commasep(modelclasses, "or")),
         call.=FALSE)
  action <- match.arg(action)
  X <- response(object)
  tl <- termsinformula(formula(object))
  if(is.null(scope)) {
    scope <- drop.scope(object)
  } else {
    if (!is.character(scope)) 
      scope <- termsinformula(update.formula(object, scope))
    if (!all(match(scope, tl, 0L) > 0L)) 
      stop("scope is not a subset of term labels")
  }
  if(length(high) == 1) high <- rep(high, length(scope)) else
  stopifnot(length(high) == length(scope))
  #' pixel resolution arguments only
  rezargs <- list(...)[c("eps", "dimyx", "xy", "rule.eps")]
  rezargs <- rezargs[!sapply(rezargs, is.null)]
  #' recognised covariates
  covars <- do.call(model.images,
                    append(list(object=object),
                           rezargs))
  W <- if(length(covars)) Window(covars[[1]]) else Window(X)
  wanted <- setdiff(scope, names(covars))
  if("x" %in% wanted) {
    covars$x <- as.im(function(x,y){x}, W)
    wanted <- setdiff(wanted, "x")
  }
  if("y" %in% wanted) {
    covars$y <- as.im(function(x,y){y}, W)
    wanted <- setdiff(wanted, "y")
  }
  if((nw <- length(wanted)) > 0) {
    #' find correspondence between original and canonical covariates
    dmat <- model.depends(object)
    orig <- colnames(dmat)
    canon <- rownames(dmat)
    mapisunique <- (colSums(dmat) == 1)
    kk <- match(wanted, orig)
    matched <- !is.na(kk)
    for(k in kk[matched]) {
      if(mapisunique[k]) {
        origname <- orig[k]
        canoname <- canon[which(dmat[,k])]
        covars[[origname]] <- covars[[canoname]]
      } 
    }
    #' deal with interactions etc
    if(any(hard <- !mapisunique[kk[matched]])) {
      nhard <- sum(hard)
      hardnames <- (wanted[matched])[hard]
      warning(paste(ngettext(nhard, "Variable", "Variables"),
                    commasep(sQuote(hardnames)),
                    ngettext(nhard, "is", "are"),
                    "difficult to remove from the model"),
            call.=FALSE)
    }
    wanted <- setdiff(wanted, names(covars))
    nw <- length(wanted)
    if(nw > 0) {
      warning(paste(ngettext(nw, "Variable", "Variables"),
                    commasep(sQuote(wanted)),
                    ngettext(nw, "is", "are"),
                    "not available in the model"),
              call.=FALSE)
      #' give up and remove these variables from the scope.
      scope <- setdiff(scope, wanted)
    }
  }
  #' 
  ns <- length(scope)
  result <- vector(mode="list", length=ns)
  for(i in seq_len(ns)) {
    tt <- scope[i]
    drop.i <- as.formula(paste(". ~ . - ", tt))
    fit.i <- update(object, drop.i, env=environment(formula(object)))
    cov.i <- covars[[tt]]
    result[[i]] <-
      switch(action,
             roc = {
               roc(X, cov.i, ..., baseline=fit.i, high=high[i])
             },
             rhohat = {
               rhohat(fit.i, cov.i, ..., covname=tt)
             },
             berman.test = {
               berman.test(fit.i, cov.i, ..., covname=tt)
             },
             cdf.test = {
               cdf.test(fit.i, cov.i, ..., covname=tt)
             })
  }
  names(result) <- scope
  return(as.anylist(result))
}`

