const rtdal007903Source0011 = `getglmfit.slrm <- function(object, ...) { object$Fit$FIT }`

const rtdal007903Source0012 = `getglmsubset.slrm <- function(object, ...) {
  su <- getCall(object)$subset
  if(is.null(su)) return(rep(TRUE, nrow(model.matrix(object))))
  su <- try(eval(su, envir=environment(terms(object))))
  if(inherits(su, "try-error")) 
    warning("Internal error: unable to evaluate the subset")
  return(su)
}`

const rtdal007903Source0014 = `logLik.slrm <- function(object, ..., adjust=TRUE) {
  FIT  <- object$Fit$FIT
  ll <- -deviance(FIT)/2
  if(adjust) {
    sumYloga <- object$Data$sumYloga
    ll <- ll - sumYloga
  }
  attr(ll, "df") <- length(coef(object))
  class(ll) <- "logLik"
  return(ll)
}`

const rtdal007903Source0015 = `fitted.slrm <- function(object, ..., type="probabilities",
                        dataonly=FALSE, leaveoneout=FALSE) {
  trap.extra.arguments(...)
  if(!dataonly) {
    ## Predict at every pixel
    Z <- predict(object, type=type, leaveoneout=leaveoneout)
    return(Z)
  } else {
    ## Require fitted values at original point locations
    X <- response(object)
    if(!leaveoneout) {
      ## predict at every pixel, extract fitted values at original points
      Z <- predict(object, type=type)
      ZX <- safelookup(Z, X)
    } else {
      ## leave-one-out calculation, brute force
      nX <- npoints(X)
      ZX <- numeric(nX)
      for(i in seq_len(nX)) {
        model.i <- updateData(object, X[-i])
        Z.i <- predict(model.i, type=type)
        ZX[i] <- safelookup(Z.i, X[i])
      }
    }
    return(ZX)
  } 
}`

