const rtdal007913Source0002 = `print.traj <- function(x, ...) {
  cat("Trajectory of function evaluations\n")
  cat(paste0("Variables: ", commasep(sQuote(colnames(x))), "\n"))
  invisible(NULL)
}`

const rtdal007913Source0003 = `plot.traj <- function(x, ..., show.ends=TRUE, add=FALSE, xlab=NULL, ylab=NULL) {
  if(add) {
    ## add to existing plot (handles 'type')
    points(x[,1], x[,2], ...)
  } else {
    ## new plot
    nama <- colnames(x)
    plot(x[,1], x[,2],
         xlab=xlab %orifnull% nama[1],
         ylab=ylab %orifnull% nama[2], ...)
  }
  ## indicate first and last states
  if(show.ends) {
    n <- nrow(x)
    points(x[1,1], x[1,2], pch=1, col="blue", cex=3)
    points(x[n,1], x[n,2], pch=3, col="red", cex=2)
  }
  return(invisible(NULL))
}`

const rtdal007913Source0004 = `lines.traj <- function(x, ..., directed=FALSE) {
  xx <- x[,1]
  yy <- x[,2]
  nn <- length(xx)
  if(directed) {
    arrows(xx[-nn], yy[-nn], xx[-1], yy[-1], ...)
  } else {
    lines(x=xx, y=yy, ...)
  }
  return(invisible(NULL))
}`

