	runtime.SetGlobal(ctx, "FULLTEST", runtime.MustCallPrimitive(ctx, "(", runtime.PrimitiveArg(runtime.MustCallPrimitive(ctx, ">", runtime.PrimitiveArg(runtime.MustCallPrimitive(ctx, "nchar", runtime.PrimitiveArg(runtime.MustCallPrimitive(ctx, "Sys.getenv", runtime.PrimitiveArg(runtime.CharacterScalar("SPATSTAT_TEST")), runtime.NamedPrimitiveArg("unset", runtime.CharacterScalar("")))))), runtime.PrimitiveArg(runtime.NumericVector(0))))))

